B.a8B=new A.hf("first-weeks",B.ja,"\u041f\u0435\u0440\u0432\u044b\u0435 \u043d\u0435\u0434\u0435\u043b\u0438 \u0434\u043e\u043c\u0430: \u043a\u0430\u043a \u0432\u0441\u0451 \u0443\u0441\u043f\u0435\u0432\u0430\u0442\u044c","\u041c\u0430\u043b\u044b\u0448 \u0437\u0430\u0434\u0430\u0451\u0442 \u0440\u0438\u0442\u043c, \u0430 \u0432\u044b \u0443\u0447\u0438\u0442\u0435\u0441\u044c \u043f\u043e\u0434\u0441\u0442\u0440\u0430\u0438\u0432\u0430\u0442\u044c\u0441\u044f. \u041d\u0435\u0441\u043a\u043e\u043b\u044c\u043a\u043e \u043f\u0440\u043e\u0441\u0442\u044b\u0445 \u043f\u0440\u0438\u0451\u043c\u043e\u0432, \u043a\u043e\u0442\u043e\u0440\u044b\u0435 \u044d\u043a\u043e\u043d\u043e\u043c\u044f\u0442 \u0441\u0438\u043b\u044b.","\u041f\u0435\u0440\u0432\u044b\u0435 \u043d\u0435\u0434\u0435\u043b\u0438 \u0441 \u043c\u0430\u043b\u044b\u0448\u043e\u043c \u043f\u043e\u0447\u0442\u0438 \u0443 \u0432\u0441\u0435\u0445 \u043f\u0440\u043e\u0445\u043e\u0434\u044f\u0442 \u0432 \u0442\u0443\u043c\u0430\u043d\u0435: \u043a\u043e\u0440\u043e\u0442\u043a\u0438\u0435 \u0441\u043d\u044b,\n\u043a\u043e\u0440\u043c\u043b\u0435\u043d\u0438\u044f, \u043f\u043e\u0434\u0433\u0443\u0437\u043d\u0438\u043a\u0438, \u0433\u043e\u0441\u0442\u0438. \u042d\u0442\u043e \u043d\u043e\u0440\u043c\u0430\u043b\u044c\u043d\u043e. \u0426\u0435\u043b\u044c \u0441\u0435\u0439\u0447\u0430\u0441 \u2014 \u043d\u0435 \u0438\u0434\u0435\u0430\u043b\u044c\u043d\u044b\u0439\n\u043f\u043e\u0440\u044f\u0434\u043e\u043a, \u0430 \u0447\u0442\u043e\u0431\u044b \u0443 \u0432\u0430\u0441 \u043e\u0441\u0442\u0430\u0432\u0430\u043b\u0438\u0441\u044c \u0441\u0438\u043b\u044b.\n\n## \u0423\u0441\u0442\u0440\u043e\u0439\u0442\u0435 \xab\u0441\u0442\u0430\u043d\u0446\u0438\u0438\xbb\n\u0421\u043e\u0431\u0435\u0440\u0438\u0442\u0435 \u0432\u0441\u0451 \u043d\u0443\u0436\u043d\u043e\u0435 \u0432 \u0434\u0432\u0443\u0445-\u0442\u0440\u0451\u0445 \u043c\u0435\u0441\u0442\u0430\u0445, \u0433\u0434\u0435 \u0432\u044b \u0447\u0430\u0449\u0435 \u0432\u0441\u0435\u0433\u043e \u0431\u044b\u0432\u0430\u0435\u0442\u0435 \u0441 \u043c\u0430\u043b\u044b\u0448\u043e\u043c.\n- \u0423 \u043f\u0435\u043b\u0435\u043d\u0430\u043b\u044c\u043d\u043e\u0433\u043e \u043c\u0435\u0441\u0442\u0430: \u043f\u043e\u0434\u0433\u0443\u0437\u043d\u0438\u043a\u0438, \u0441\u0430\u043b\u0444\u0435\u0442\u043a\u0438, \u043a\u0440\u0435\u043c, \u0441\u043c\u0435\u043d\u043d\u0430\u044f \u043e\u0434\u0435\u0436\u0434\u0430, \u043f\u0430\u043a\u0435\u0442\u044b.\n- \u0423 \u043c\u0435\u0441\u0442\u0430, \u0433\u0434\u0435 \u0432\u044b \u043a\u043e\u0440\u043c\u0438\u0442\u0435: \u0432\u043e\u0434\u0430 \u0434\u043b\u044f \u0432\u0430\u0441, \u0442\u0435\u043b\u0435\u0444\u043e\u043d \u0441 \u0437\u0430\u0440\u044f\u0434\u043a\u043e\u0439, \u043f\u0435\u043b\u0451\u043d\u043a\u0430.\n- \u041d\u0430 \u043d\u043e\u0447\u044c: \u043f\u0440\u0438\u0433\u043b\u0443\u0448\u0451\u043d\u043d\u044b\u0439 \u0441\u0432\u0435\u0442, \u0447\u0442\u043e\u0431\u044b \u043d\u0435 \u0432\u043a\u043b\u044e\u0447\u0430\u0442\u044c \u0432\u0435\u0440\u0445\u043d\u0438\u0439.\n\n## \u0414\u0435\u043b\u0438\u0442\u0435 \u043e\u0431\u044f\u0437\u0430\u043d\u043d\u043e\u0441\u0442\u0438 \u0437\u0430\u0440\u0430\u043d\u0435\u0435\n\u0414\u043e\u0433\u043e\u0432\u043e\u0440\u0438\u0442\u0435\u0441\u044c, \u043a\u0442\u043e \u0447\u0442\u043e \u0434\u0435\u043b\u0430\u0435\u0442, \u0434\u043e \u0442\u043e\u0433\u043e \u043a\u0430\u043a \u043e\u0431\u0430 \u0443\u0441\u0442\u0430\u043d\u0435\u0442\u0435. \u041d\u0430\u043f\u0440\u0438\u043c\u0435\u0440, \u043e\u0434\u0438\u043d\n\u043a\u0443\u043f\u0430\u0435\u0442 \u0438 \u0443\u043a\u043b\u0430\u0434\u044b\u0432\u0430\u0435\u0442 \u0432\u0435\u0447\u0435\u0440\u043e\u043c, \u0434\u0440\u0443\u0433\u043e\u0439 \u0431\u0435\u0440\u0451\u0442 \u0440\u0430\u043d\u043d\u0435\u0435 \u0443\u0442\u0440\u043e. \u041e\u0431\u044f\u0437\u0430\u043d\u043d\u043e\u0441\u0442\u0438 \u043c\u043e\u0436\u043d\u043e\n\u043c\u0435\u043d\u044f\u0442\u044c, \u0433\u043b\u0430\u0432\u043d\u043e\u0435 \u2014 \u0447\u0442\u043e\u0431\u044b \u043d\u0438\u043a\u0442\u043e \u043d\u0435 \u0442\u0430\u0449\u0438\u043b \u0432\u0441\u0451 \u043e\u0434\u0438\u043d.\n\n## \u041f\u0440\u0438\u043d\u0438\u043c\u0430\u0439\u0442\u0435 \u043f\u043e\u043c\u043e\u0449\u044c \u043a\u043e\u043d\u043a\u0440\u0435\u0442\u043d\u043e\n\xab\u0427\u0435\u043c \u043f\u043e\u043c\u043e\u0447\u044c?\xbb \u2014 \u0442\u0440\u0443\u0434\u043d\u044b\u0439 \u0432\u043e\u043f\u0440\u043e\u0441, \u043a\u043e\u0433\u0434\u0430 \u0432\u044b \u043d\u0435 \u0432\u044b\u0441\u043f\u0430\u043b\u0438\u0441\u044c. \u0414\u0435\u0440\u0436\u0438\u0442\u0435 \u0441\u043f\u0438\u0441\u043e\u043a\n\u0433\u043e\u0442\u043e\u0432\u044b\u0445 \u043e\u0442\u0432\u0435\u0442\u043e\u0432:\n- \u043f\u0440\u0438\u0433\u043e\u0442\u043e\u0432\u0438\u0442\u044c \u0435\u0434\u0443 \u0438\u043b\u0438 \u043f\u0440\u0438\u0432\u0435\u0437\u0442\u0438 \u043f\u0440\u043e\u0434\u0443\u043a\u0442\u044b;\n- \u043f\u043e\u0433\u0443\u043b\u044f\u0442\u044c \u0441 \u043a\u043e\u043b\u044f\u0441\u043a\u043e\u0439 \u0447\u0430\u0441, \u043f\u043e\u043a\u0430 \u0432\u044b \u0441\u043f\u0438\u0442\u0435;\n- \u0437\u0430\u0431\u0440\u0430\u0442\u044c \u0441\u0442\u0438\u0440\u043a\u0443, \u043f\u043e\u043c\u044b\u0442\u044c \u043f\u043e\u0441\u0443\u0434\u0443;\n- \u043f\u043e\u0441\u0438\u0434\u0435\u0442\u044c \u0441 \u043c\u0430\u043b\u044b\u0448\u043e\u043c, \u043f\u043e\u043a\u0430 \u0432\u044b \u0432 \u0434\u0443\u0448\u0435.\n\n## \u0417\u0430\u043f\u0438\u0441\u044b\u0432\u0430\u0439\u0442\u0435, \u0430 \u043d\u0435 \u0437\u0430\u043f\u043e\u043c\u0438\u043d\u0430\u0439\u0442\u0435\n\u041a\u043e\u0433\u0434\u0430 \u0431\u044b\u043b \u043f\u043e\u0441\u043b\u0435\u0434\u043d\u0438\u0439 \u043f\u043e\u0434\u0433\u0443\u0437\u043d\u0438\u043a, \u0441\u043a\u043e\u043b\u044c\u043a\u043e \u0441\u043f\u0430\u043b, \u0447\u0442\u043e \u0441\u043a\u0430\u0437\u0430\u043b \u0432\u0440\u0430\u0447 \u2014 \u0432 \u043f\u0435\u0440\u0432\u044b\u0435 \u043d\u0435\u0434\u0435\u043b\u0438\n\u044d\u0442\u043e \u0431\u044b\u0441\u0442\u0440\u043e \u043f\u0443\u0442\u0430\u0435\u0442\u0441\u044f. \u041e\u0442\u043c\u0435\u0447\u0430\u0439\u0442\u0435 \u0432 \u0434\u043d\u0435\u0432\u043d\u0438\u043a\u0435 \u0438 \u0442\u0440\u0435\u043a\u0435\u0440\u0430\u0445: \u0442\u0430\u043a \u043f\u0440\u043e\u0449\u0435 \u0437\u0430\u043c\u0435\u0442\u0438\u0442\u044c\n\u0438\u0437\u043c\u0435\u043d\u0435\u043d\u0438\u044f \u0438 \u043e\u0442\u0432\u0435\u0442\u0438\u0442\u044c \u043d\u0430 \u0432\u043e\u043f\u0440\u043e\u0441\u044b \u043f\u0435\u0434\u0438\u0430\u0442\u0440\u0430.\n\n> \u041d\u0435 \u0441\u0440\u0430\u0432\u043d\u0438\u0432\u0430\u0439\u0442\u0435 \u0441\u0435\u0431\u044f \u0441 \u043a\u0430\u0440\u0442\u0438\u043d\u043a\u0430\u043c\u0438 \u0438\u0437 \u0441\u043e\u0446\u0441\u0435\u0442\u0435\u0439. \u0423 \u043a\u0430\u0436\u0434\u043e\u0439 \u0441\u0435\u043c\u044c\u0438 \u0441\u0432\u043e\u0439 \u0442\u0435\u043c\u043f,\n> \u0438 \u043e\u043d \u043c\u0435\u043d\u044f\u0435\u0442\u0441\u044f \u043a\u0430\u0436\u0434\u044b\u0435 \u043f\u0430\u0440\u0443 \u043d\u0435\u0434\u0435\u043b\u044c.\n",B.jw,!1,0,60)
B.a8L=new A.hf("walk-bag",B.ja,"\u0427\u0442\u043e \u043f\u043e\u043b\u043e\u0436\u0438\u0442\u044c \u0432 \u0441\u0443\u043c\u043a\u0443 \u043d\u0430 \u043f\u0440\u043e\u0433\u0443\u043b\u043a\u0443","\u0421\u043f\u0438\u0441\u043e\u043a, \u0447\u0442\u043e\u0431\u044b \u043d\u0435 \u0432\u043e\u0437\u0432\u0440\u0430\u0449\u0430\u0442\u044c\u0441\u044f \u0434\u043e\u043c\u043e\u0439 \u0441 \u043f\u043e\u043b\u043f\u0443\u0442\u0438. \u0421\u043e\u0431\u0435\u0440\u0438\u0442\u0435 \u0441\u0443\u043c\u043a\u0443 \u043e\u0434\u0438\u043d \u0440\u0430\u0437 \u0438 \u043f\u043e\u043f\u043e\u043b\u043d\u044f\u0439\u0442\u0435 \u043f\u043e\u0441\u043b\u0435 \u043f\u0440\u043e\u0433\u0443\u043b\u043a\u0438.","\u0423\u0434\u043e\u0431\u043d\u0435\u0435 \u0432\u0441\u0435\u0433\u043e \u0434\u0435\u0440\u0436\u0430\u0442\u044c \u043e\u0442\u0434\u0435\u043b\u044c\u043d\u0443\u044e \u0441\u0443\u043c\u043a\u0443, \u043a\u043e\u0442\u043e\u0440\u0430\u044f \u0432\u0441\u0435\u0433\u0434\u0430 \u0441\u043e\u0431\u0440\u0430\u043d\u0430. \u0412\u0435\u0440\u043d\u0443\u043b\u0438\u0441\u044c \u2014\n\u043f\u043e\u043f\u043e\u043b\u043d\u0438\u043b\u0438 \u0442\u043e, \u0447\u0442\u043e \u0437\u0430\u043a\u043e\u043d\u0447\u0438\u043b\u043e\u0441\u044c.\n\n## \u0414\u043b\u044f \u043c\u0430\u043b\u044b\u0448\u0430\n- \u041f\u043e\u0434\u0433\u0443\u0437\u043d\u0438\u043a\u0438 \u0441 \u0437\u0430\u043f\u0430\u0441\u043e\u043c: \u043d\u0430 \u043e\u0434\u0438\u043d-\u0434\u0432\u0430 \u0431\u043e\u043b\u044c\u0448\u0435, \u0447\u0435\u043c \u043e\u0431\u044b\u0447\u043d\u043e \u0443\u0445\u043e\u0434\u0438\u0442 \u0437\u0430 \u044d\u0442\u043e \u0432\u0440\u0435\u043c\u044f.\n- \u0412\u043b\u0430\u0436\u043d\u044b\u0435 \u0441\u0430\u043b\u0444\u0435\u0442\u043a\u0438 \u0438 \u043f\u0430\u043a\u0435\u0442\u044b \u0434\u043b\u044f \u0438\u0441\u043f\u043e\u043b\u044c\u0437\u043e\u0432\u0430\u043d\u043d\u044b\u0445 \u043f\u043e\u0434\u0433\u0443\u0437\u043d\u0438\u043a\u043e\u0432.\n- \u041f\u0435\u043b\u0451\u043d\u043a\u0430 \u0438\u043b\u0438 \u043e\u0434\u043d\u043e\u0440\u0430\u0437\u043e\u0432\u0430\u044f \u043f\u043e\u0434\u0441\u0442\u0438\u043b\u043a\u0430 \u0434\u043b\u044f \u043f\u0435\u043b\u0435\u043d\u0430\u043d\u0438\u044f.\n- \u0421\u043c\u0435\u043d\u043d\u0430\u044f \u043e\u0434\u0435\u0436\u0434\u0430: \u0431\u043e\u0434\u0438 \u0438 \u043f\u043e\u043b\u0437\u0443\u043d\u043a\u0438, \u0432 \u0445\u043e\u043b\u043e\u0434\u043d\u043e\u0435 \u0432\u0440\u0435\u043c\u044f \u2014 \u0437\u0430\u043f\u0430\u0441\u043d\u044b\u0435 \u043d\u043e\u0441\u043a\u0438.\n- \u0415\u0434\u0430, \u0435\u0441\u043b\u0438 \u043c\u0430\u043b\u044b\u0448 \u043d\u0430 \u0441\u043c\u0435\u0441\u0438 \u0438\u043b\u0438 \u043f\u0440\u0438\u043a\u043e\u0440\u043c\u0435: \u0431\u0443\u0442\u044b\u043b\u043e\u0447\u043a\u0430, \u043f\u043e\u0440\u0446\u0438\u044f, \u043b\u043e\u0436\u043a\u0430.\n- \u041b\u044e\u0431\u0438\u043c\u0430\u044f \u0438\u0433\u0440\u0443\u0448\u043a\u0430 \u0438\u043b\u0438 \u043f\u043e\u0433\u0440\u0435\u043c\u0443\u0448\u043a\u0430.\n- \u0414\u043e\u0436\u0434\u0435\u0432\u0438\u043a \u043d\u0430 \u043a\u043e\u043b\u044f\u0441\u043a\u0443 \u0438 \u0447\u0442\u043e-\u0442\u043e \u043e\u0442 \u0441\u043e\u043b\u043d\u0446\u0430 \u043b\u0435\u0442\u043e\u043c.\n\n## \u0414\u043b\u044f \u0432\u0430\u0441\n- \u0412\u043e\u0434\u0430 \u0438 \u043f\u0435\u0440\u0435\u043a\u0443\u0441.\n- \u0422\u0435\u043b\u0435\u0444\u043e\u043d \u0441 \u0437\u0430\u0440\u044f\u0434\u043a\u043e\u0439, \u043b\u0443\u0447\u0448\u0435 \u0438 \u0432\u043d\u0435\u0448\u043d\u0438\u0439 \u0430\u043a\u043a\u0443\u043c\u0443\u043b\u044f\u0442\u043e\u0440.\n- \u0412\u043b\u0430\u0436\u043d\u044b\u0435 \u0441\u0430\u043b\u0444\u0435\u0442\u043a\u0438 \u0434\u043b\u044f \u0440\u0443\u043a.\n- \u0421\u043c\u0435\u043d\u043d\u0430\u044f \u0444\u0443\u0442\u0431\u043e\u043b\u043a\u0430: \u043f\u0440\u0438\u0433\u043e\u0434\u0438\u0442\u0441\u044f \u0447\u0430\u0449\u0435, \u0447\u0435\u043c \u043a\u0430\u0436\u0435\u0442\u0441\u044f.\n- \u0424\u043e\u0442\u043e \u043f\u043e\u043b\u0438\u0441\u0430 \u041e\u041c\u0421 \u043c\u0430\u043b\u044b\u0448\u0430 \u0432 \u0442\u0435\u043b\u0435\u0444\u043e\u043d\u0435 \u043d\u0430 \u0432\u0441\u044f\u043a\u0438\u0439 \u0441\u043b\u0443\u0447\u0430\u0439.\n\n> \u0415\u0441\u043b\u0438 \u043c\u0430\u043b\u044b\u0448\u0443 \u043d\u0430\u0437\u043d\u0430\u0447\u0435\u043d\u044b \u043b\u0435\u043a\u0430\u0440\u0441\u0442\u0432\u0430, \u0441\u043f\u0440\u043e\u0441\u0438\u0442\u0435 \u0443 \u043f\u0435\u0434\u0438\u0430\u0442\u0440\u0430, \u043d\u0443\u0436\u043d\u043e \u043b\u0438 \u0431\u0440\u0430\u0442\u044c \u0438\u0445\n> \u0441 \u0441\u043e\u0431\u043e\u0439 \u0438 \u043a\u0430\u043a \u0445\u0440\u0430\u043d\u0438\u0442\u044c \u0432 \u0434\u043e\u0440\u043e\u0433\u0435.\n",B.jw,!1,0,365)
B.a8J=new A.hf("doctor-visit",B.a4S,"\u041a\u0430\u043a \u043f\u043e\u0434\u0433\u043e\u0442\u043e\u0432\u0438\u0442\u044c\u0441\u044f \u043a \u043f\u0440\u0438\u0451\u043c\u0443 \u043f\u0435\u0434\u0438\u0430\u0442\u0440\u0430","\u0427\u0442\u043e \u0432\u0437\u044f\u0442\u044c \u0441 \u0441\u043e\u0431\u043e\u0439, \u043a\u0430\u043a \u043d\u0435 \u0437\u0430\u0431\u044b\u0442\u044c \u0432\u043e\u043f\u0440\u043e\u0441\u044b \u0438 \u043a\u0430\u043a \u043f\u043e\u043a\u0430\u0437\u0430\u0442\u044c \u0432\u0440\u0430\u0447\u0443 \u0437\u0430\u043f\u0438\u0441\u0438 \u0438\u0437 \u043f\u0440\u0438\u043b\u043e\u0436\u0435\u043d\u0438\u044f.","\u041f\u0440\u0438\u0451\u043c \u0443 \u043f\u0435\u0434\u0438\u0430\u0442\u0440\u0430 \u043e\u0431\u044b\u0447\u043d\u043e \u043a\u043e\u0440\u043e\u0442\u043a\u0438\u0439, \u0430 \u043c\u0430\u043b\u044b\u0448 \u043c\u043e\u0436\u0435\u0442 \u043a\u0430\u043f\u0440\u0438\u0437\u043d\u0438\u0447\u0430\u0442\u044c. \u041f\u043e\u0434\u0433\u043e\u0442\u043e\u0432\u043a\u0430\n\u0437\u0430\u0440\u0430\u043d\u0435\u0435 \u043f\u043e\u043c\u043e\u0433\u0430\u0435\u0442 \u043d\u0435 \u0437\u0430\u0431\u044b\u0442\u044c \u0432\u0430\u0436\u043d\u043e\u0435.\n\n## \u0414\u043e\u043a\u0443\u043c\u0435\u043d\u0442\u044b\n- \u041f\u043e\u043b\u0438\u0441 \u041e\u041c\u0421 \u043c\u0430\u043b\u044b\u0448\u0430 (\u0431\u0443\u043c\u0430\u0436\u043d\u044b\u0439 \u0438\u043b\u0438 \u043d\u043e\u043c\u0435\u0440 \u0432 \u0442\u0435\u043b\u0435\u0444\u043e\u043d\u0435).\n- \u0421\u041d\u0418\u041b\u0421 \u0438 \u0441\u0432\u0438\u0434\u0435\u0442\u0435\u043b\u044c\u0441\u0442\u0432\u043e \u043e \u0440\u043e\u0436\u0434\u0435\u043d\u0438\u0438 \u2014 \u043e\u0441\u043e\u0431\u0435\u043d\u043d\u043e \u043d\u0430 \u043f\u0435\u0440\u0432\u044b\u0445 \u043f\u0440\u0438\u0451\u043c\u0430\u0445.\n- \u0412\u0430\u0448 \u043f\u0430\u0441\u043f\u043e\u0440\u0442.\n- \u041f\u0440\u0438\u0432\u0438\u0432\u043e\u0447\u043d\u044b\u0439 \u0441\u0435\u0440\u0442\u0438\u0444\u0438\u043a\u0430\u0442, \u0435\u0441\u043b\u0438 \u043e\u043d \u0443 \u0432\u0430\u0441 \u043d\u0430 \u0440\u0443\u043a\u0430\u0445.\n- \u0412\u044b\u043f\u0438\u0441\u043a\u0430 \u0438\u0437 \u0440\u043e\u0434\u0434\u043e\u043c\u0430 \u2014 \u043d\u0430 \u043f\u0435\u0440\u0432\u044b\u0435 \u0432\u0438\u0437\u0438\u0442\u044b \u043f\u043e\u0441\u043b\u0435 \u0432\u044b\u043f\u0438\u0441\u043a\u0438.\n\n## \u0412\u043e\u043f\u0440\u043e\u0441\u044b \u2014 \u0437\u0430\u0440\u0430\u043d\u0435\u0435\n\u0417\u0430\u043f\u0438\u0441\u044b\u0432\u0430\u0439\u0442\u0435 \u0432\u043e\u043f\u0440\u043e\u0441\u044b \u0432 \u0434\u043d\u0435\u0432\u043d\u0438\u043a \u0441\u0440\u0430\u0437\u0443, \u043a\u0430\u043a \u043e\u043d\u0438 \u043f\u043e\u044f\u0432\u043b\u044f\u044e\u0442\u0441\u044f: \u043d\u0430 \u043f\u0440\u0438\u0451\u043c\u0435 \u043e\u043d\u0438\n\u043b\u0435\u0433\u043a\u043e \u0432\u044b\u043b\u0435\u0442\u0430\u044e\u0442 \u0438\u0437 \u0433\u043e\u043b\u043e\u0432\u044b. \u041f\u0435\u0440\u0435\u0434 \u0432\u0438\u0437\u0438\u0442\u043e\u043c \u043f\u0440\u043e\u043b\u0438\u0441\u0442\u0430\u0439\u0442\u0435 \u0438 \u043e\u0442\u043c\u0435\u0442\u044c\u0442\u0435 \u0441\u0430\u043c\u044b\u0435 \u0432\u0430\u0436\u043d\u044b\u0435 \u2014\n\u0441 \u043d\u0438\u0445 \u0438 \u043d\u0430\u0447\u043d\u0438\u0442\u0435.\n\n## \u0421\u0432\u043e\u0434\u043a\u0430 \u0434\u043b\u044f \u0432\u0440\u0430\u0447\u0430\n\u0412 \u043f\u0440\u0438\u043b\u043e\u0436\u0435\u043d\u0438\u0438 \u0435\u0441\u0442\u044c \xab\u041e\u0442\u0447\u0451\u0442 \u0434\u043b\u044f \u0432\u0440\u0430\u0447\u0430\xbb: \u0441\u043e\u043d, \u043f\u043e\u0434\u0433\u0443\u0437\u043d\u0438\u043a\u0438, \u043f\u0440\u0438\u043a\u043e\u0440\u043c \u0438 \u0440\u0435\u0430\u043a\u0446\u0438\u0438,\n\u0440\u043e\u0441\u0442 \u0438 \u0432\u0435\u0441, \u043f\u0440\u0438\u0432\u0438\u0432\u043a\u0438 \u0438 \u0430\u043b\u043b\u0435\u0440\u0433\u0438\u0438 \u0437\u0430 \u043d\u0435\u0434\u0435\u043b\u044e, \u043c\u0435\u0441\u044f\u0446 \u0438\u043b\u0438 \u0442\u0440\u0438 \u043c\u0435\u0441\u044f\u0446\u0430. \u0415\u0433\u043e \u043c\u043e\u0436\u043d\u043e\n\u043f\u043e\u043a\u0430\u0437\u0430\u0442\u044c \u0441 \u044d\u043a\u0440\u0430\u043d\u0430 \u0438\u043b\u0438 \u043e\u0442\u043f\u0440\u0430\u0432\u0438\u0442\u044c \u0444\u0430\u0439\u043b\u043e\u043c PDF. \u041b\u0438\u0447\u043d\u044b\u0435 \u0437\u0430\u043f\u0438\u0441\u0438 \u0434\u043d\u0435\u0432\u043d\u0438\u043a\u0430 \u0432 \u0441\u0432\u043e\u0434\u043a\u0443\n\u043d\u0435 \u043f\u043e\u043f\u0430\u0434\u0430\u044e\u0442.\n\n\u0427\u0442\u043e\u0431\u044b \u0446\u0438\u0444\u0440\u044b \u0431\u044b\u043b\u0438 \u043f\u043e\u043b\u0435\u0437\u043d\u044b\u043c\u0438, \u043e\u0442\u043c\u0435\u0447\u0430\u0439\u0442\u0435 \u0441\u043e\u043d \u0438 \u043f\u043e\u0434\u0433\u0443\u0437\u043d\u0438\u043a\u0438 \u0445\u043e\u0442\u044f \u0431\u044b \u043d\u0435\u0441\u043a\u043e\u043b\u044c\u043a\u043e \u0434\u043d\u0435\u0439\n\u043f\u0435\u0440\u0435\u0434 \u043f\u0440\u0438\u0451\u043c\u043e\u043c.\n\n## \u0414\u043b\u044f \u043c\u0430\u043b\u044b\u0448\u0430\n- \u041f\u0435\u043b\u0451\u043d\u043a\u0430 \u043d\u0430 \u043f\u0435\u043b\u0435\u043d\u0430\u043b\u044c\u043d\u044b\u0439 \u0441\u0442\u043e\u043b.\n- \u041f\u043e\u0434\u0433\u0443\u0437\u043d\u0438\u043a, \u0441\u0430\u043b\u0444\u0435\u0442\u043a\u0438, \u0441\u043c\u0435\u043d\u043d\u0430\u044f \u043e\u0434\u0435\u0436\u0434\u0430.\n- \u0415\u0434\u0430 \u0438\u043b\u0438 \u0432\u043e\u0434\u0430, \u0435\u0441\u043b\u0438 \u043f\u0440\u0438\u0451\u043c \u0437\u0430\u0442\u044f\u043d\u0435\u0442\u0441\u044f.\n- \u0418\u0433\u0440\u0443\u0448\u043a\u0430, \u043a\u043e\u0442\u043e\u0440\u0430\u044f \u043e\u0442\u0432\u043b\u0435\u0447\u0451\u0442 \u0432\u043e \u0432\u0440\u0435\u043c\u044f \u043e\u0441\u043c\u043e\u0442\u0440\u0430.\n\n## \u041f\u043e\u0441\u043b\u0435 \u043f\u0440\u0438\u0451\u043c\u0430\n\u0421\u0440\u0430\u0437\u0443 \u0437\u0430\u043f\u0438\u0448\u0438\u0442\u0435 \u0440\u0435\u043a\u043e\u043c\u0435\u043d\u0434\u0430\u0446\u0438\u0438 \u0438 \u043d\u0430\u0437\u043d\u0430\u0447\u0435\u043d\u0438\u044f \u2014 \u0432 \u0434\u043d\u0435\u0432\u043d\u0438\u043a \u0438\u043b\u0438 \u0437\u0430\u043c\u0435\u0442\u043a\u0443 \u043a \u0441\u043e\u0431\u044b\u0442\u0438\u044e.\n\u0415\u0441\u043b\u0438 \u0432\u0440\u0430\u0447 \u043d\u0430\u0437\u0432\u0430\u043b \u0434\u0430\u0442\u0443 \u0441\u043b\u0435\u0434\u0443\u044e\u0449\u0435\u0433\u043e \u0432\u0438\u0437\u0438\u0442\u0430 \u0438\u043b\u0438 \u043f\u0440\u0438\u0432\u0438\u0432\u043a\u0438, \u0434\u043e\u0431\u0430\u0432\u044c\u0442\u0435 \u0435\u0451 \u0432 \u043a\u0430\u043b\u0435\u043d\u0434\u0430\u0440\u044c\n\u0441 \u043d\u0430\u043f\u043e\u043c\u0438\u043d\u0430\u043d\u0438\u0435\u043c.\n",B.jw,!1,null,null)
B.a8H=new A.hf("documents",B.a4T,"\u0414\u043e\u043a\u0443\u043c\u0435\u043d\u0442\u044b \u043f\u043e\u0441\u043b\u0435 \u0440\u043e\u0436\u0434\u0435\u043d\u0438\u044f: \u0447\u0442\u043e \u0438 \u0432 \u043a\u0430\u043a\u043e\u043c \u043f\u043e\u0440\u044f\u0434\u043a\u0435","\u0421\u0432\u0438\u0434\u0435\u0442\u0435\u043b\u044c\u0441\u0442\u0432\u043e \u043e \u0440\u043e\u0436\u0434\u0435\u043d\u0438\u0438, \u0421\u041d\u0418\u041b\u0421, \u043f\u043e\u043b\u0438\u0441 \u041e\u041c\u0421, \u043f\u0440\u043e\u043f\u0438\u0441\u043a\u0430 \u0438 \u0432\u044b\u043f\u043b\u0430\u0442\u044b \u2014 \u043a\u043e\u0440\u043e\u0442\u043a\u043e \u043e \u0442\u043e\u043c, \u0447\u0442\u043e \u043e\u0444\u043e\u0440\u043c\u0438\u0442\u044c \u0432 \u043f\u0435\u0440\u0432\u044b\u0435 \u043c\u0435\u0441\u044f\u0446\u044b \u0432 \u0420\u043e\u0441\u0441\u0438\u0438.","> \u041f\u0440\u0430\u0432\u0438\u043b\u0430 \u0438 \u0441\u0440\u043e\u043a\u0438 \u043c\u0435\u043d\u044f\u044e\u0442\u0441\u044f. \u041f\u0435\u0440\u0435\u0434 \u043f\u043e\u0445\u043e\u0434\u043e\u043c \u0432 \u0417\u0410\u0413\u0421 \u0438\u043b\u0438 \u041c\u0424\u0426 \u043f\u0440\u043e\u0432\u0435\u0440\u044c\u0442\u0435 \u0430\u043a\u0442\u0443\u0430\u043b\u044c\u043d\u044b\u0439\n> \u043f\u043e\u0440\u044f\u0434\u043e\u043a \u043d\u0430 \u0413\u043e\u0441\u0443\u0441\u043b\u0443\u0433\u0430\u0445. \u0412 \u0434\u0440\u0443\u0433\u0438\u0445 \u0441\u0442\u0440\u0430\u043d\u0430\u0445 \u0421\u041d\u0413 \u043f\u043e\u0440\u044f\u0434\u043e\u043a \u0441\u0432\u043e\u0439.\n\n## 1. \u0421\u0432\u0438\u0434\u0435\u0442\u0435\u043b\u044c\u0441\u0442\u0432\u043e \u043e \u0440\u043e\u0436\u0434\u0435\u043d\u0438\u0438\n\u0420\u043e\u0436\u0434\u0435\u043d\u0438\u0435 \u043d\u0443\u0436\u043d\u043e \u0437\u0430\u0440\u0435\u0433\u0438\u0441\u0442\u0440\u0438\u0440\u043e\u0432\u0430\u0442\u044c \u0432 \u0442\u0435\u0447\u0435\u043d\u0438\u0435 \u043c\u0435\u0441\u044f\u0446\u0430. \u042d\u0442\u043e \u043c\u043e\u0436\u043d\u043e \u0441\u0434\u0435\u043b\u0430\u0442\u044c \u0432 \u0417\u0410\u0413\u0421\u0435,\n\u0432 \u041c\u0424\u0426 \u0438\u043b\u0438 \u043f\u043e\u0434\u0430\u0442\u044c \u0437\u0430\u044f\u0432\u043b\u0435\u043d\u0438\u0435 \u043d\u0430 \u0413\u043e\u0441\u0443\u0441\u043b\u0443\u0433\u0430\u0445.\n- \u041c\u0435\u0434\u0438\u0446\u0438\u043d\u0441\u043a\u043e\u0435 \u0441\u0432\u0438\u0434\u0435\u0442\u0435\u043b\u044c\u0441\u0442\u0432\u043e \u043e \u0440\u043e\u0436\u0434\u0435\u043d\u0438\u0438 \u2014 \u0435\u0433\u043e \u0432\u044b\u0434\u0430\u044e\u0442 \u0432 \u0440\u043e\u0434\u0434\u043e\u043c\u0435.\n- \u041f\u0430\u0441\u043f\u043e\u0440\u0442\u0430 \u0440\u043e\u0434\u0438\u0442\u0435\u043b\u0435\u0439.\n- \u0421\u0432\u0438\u0434\u0435\u0442\u0435\u043b\u044c\u0441\u0442\u0432\u043e \u043e \u0431\u0440\u0430\u043a\u0435, \u0435\u0441\u043b\u0438 \u0432\u044b \u0432 \u0431\u0440\u0430\u043a\u0435.\n\n## 2. \u0421\u041d\u0418\u041b\u0421\n\u041e\u0431\u044b\u0447\u043d\u043e \u043e\u0444\u043e\u0440\u043c\u043b\u044f\u0435\u0442\u0441\u044f \u0441\u0430\u043c \u043f\u043e\u0441\u043b\u0435 \u0440\u0435\u0433\u0438\u0441\u0442\u0440\u0430\u0446\u0438\u0438 \u0440\u043e\u0436\u0434\u0435\u043d\u0438\u044f: \u043d\u043e\u043c\u0435\u0440 \u043f\u0440\u0438\u0445\u043e\u0434\u0438\u0442 \u0432 \u043b\u0438\u0447\u043d\u044b\u0439\n\u043a\u0430\u0431\u0438\u043d\u0435\u0442 \u043d\u0430 \u0413\u043e\u0441\u0443\u0441\u043b\u0443\u0433\u0430\u0445. \u0415\u0441\u043b\u0438 \u0447\u0435\u0440\u0435\u0437 \u043d\u0435\u0441\u043a\u043e\u043b\u044c\u043a\u043e \u043d\u0435\u0434\u0435\u043b\u044c \u0435\u0433\u043e \u0442\u0430\u043c \u043d\u0435\u0442, \u043e\u0431\u0440\u0430\u0442\u0438\u0442\u0435\u0441\u044c\n\u0432 \u041c\u0424\u0426 \u0438\u043b\u0438 \u0421\u043e\u0446\u0438\u0430\u043b\u044c\u043d\u044b\u0439 \u0444\u043e\u043d\u0434.\n\n## 3. \u041f\u043e\u043b\u0438\u0441 \u041e\u041c\u0421\n\u041e\u0444\u043e\u0440\u043c\u0438\u0442\u0435 \u0432 \u0441\u0442\u0440\u0430\u0445\u043e\u0432\u043e\u0439 \u043c\u0435\u0434\u0438\u0446\u0438\u043d\u0441\u043a\u043e\u0439 \u043e\u0440\u0433\u0430\u043d\u0438\u0437\u0430\u0446\u0438\u0438 \u0438\u043b\u0438 \u043d\u0430 \u0413\u043e\u0441\u0443\u0441\u043b\u0443\u0433\u0430\u0445. \u041f\u043e\u043d\u0430\u0434\u043e\u0431\u044f\u0442\u0441\u044f\n\u0441\u0432\u0438\u0434\u0435\u0442\u0435\u043b\u044c\u0441\u0442\u0432\u043e \u043e \u0440\u043e\u0436\u0434\u0435\u043d\u0438\u0438 \u0438 \u0421\u041d\u0418\u041b\u0421 \u043c\u0430\u043b\u044b\u0448\u0430. \u0414\u043e \u0440\u0435\u0433\u0438\u0441\u0442\u0440\u0430\u0446\u0438\u0438 \u0440\u043e\u0436\u0434\u0435\u043d\u0438\u044f \u043c\u0430\u043b\u044b\u0448\u0430\n\u043e\u0431\u0441\u043b\u0443\u0436\u0438\u0432\u0430\u044e\u0442 \u043f\u043e \u043f\u043e\u043b\u0438\u0441\u0443 \u043c\u0430\u043c\u044b.\n\n## 4. \u0420\u0435\u0433\u0438\u0441\u0442\u0440\u0430\u0446\u0438\u044f \u043f\u043e \u043c\u0435\u0441\u0442\u0443 \u0436\u0438\u0442\u0435\u043b\u044c\u0441\u0442\u0432\u0430\n\u0420\u0435\u0431\u0451\u043d\u043a\u0430 \u0440\u0435\u0433\u0438\u0441\u0442\u0440\u0438\u0440\u0443\u044e\u0442 \u043f\u043e \u0430\u0434\u0440\u0435\u0441\u0443 \u043e\u0434\u043d\u043e\u0433\u043e \u0438\u0437 \u0440\u043e\u0434\u0438\u0442\u0435\u043b\u0435\u0439 \u2014 \u0432 \u041c\u0424\u0426 \u0438\u043b\u0438 \u043d\u0430 \u0413\u043e\u0441\u0443\u0441\u043b\u0443\u0433\u0430\u0445.\n\u0420\u0435\u0433\u0438\u0441\u0442\u0440\u0430\u0446\u0438\u044f \u043f\u043e\u043d\u0430\u0434\u043e\u0431\u0438\u0442\u0441\u044f \u0434\u043b\u044f \u043f\u043e\u043b\u0438\u043a\u043b\u0438\u043d\u0438\u043a\u0438, \u0434\u0435\u0442\u0441\u043a\u043e\u0433\u043e \u0441\u0430\u0434\u0430 \u0438 \u043c\u043d\u043e\u0433\u0438\u0445 \u0432\u044b\u043f\u043b\u0430\u0442.\n\n## 5. \u0414\u0435\u0442\u0441\u043a\u0430\u044f \u043f\u043e\u043b\u0438\u043a\u043b\u0438\u043d\u0438\u043a\u0430\n\u0420\u043e\u0434\u0434\u043e\u043c \u043e\u0431\u044b\u0447\u043d\u043e \u0441\u0430\u043c \u043f\u0435\u0440\u0435\u0434\u0430\u0451\u0442 \u0441\u0432\u0435\u0434\u0435\u043d\u0438\u044f \u0432 \u043f\u043e\u043b\u0438\u043a\u043b\u0438\u043d\u0438\u043a\u0443 \u043f\u043e \u0430\u0434\u0440\u0435\u0441\u0443, \u043a\u043e\u0442\u043e\u0440\u044b\u0439 \u0432\u044b\n\u043d\u0430\u0437\u0432\u0430\u043b\u0438 \u043f\u0440\u0438 \u0432\u044b\u043f\u0438\u0441\u043a\u0435, \u0438 \u0432 \u043f\u0435\u0440\u0432\u044b\u0435 \u0434\u043d\u0438 \u043f\u0440\u0438\u0445\u043e\u0434\u0438\u0442 \u0432\u0440\u0430\u0447 \u0438\u043b\u0438 \u043c\u0435\u0434\u0441\u0435\u0441\u0442\u0440\u0430. \u0415\u0441\u043b\u0438 \u043d\u0438\u043a\u0442\u043e\n\u043d\u0435 \u043f\u0440\u0438\u0448\u0451\u043b \u0438 \u043d\u0435 \u043f\u043e\u0437\u0432\u043e\u043d\u0438\u043b, \u043f\u043e\u0437\u0432\u043e\u043d\u0438\u0442\u0435 \u0432 \u043f\u043e\u043b\u0438\u043a\u043b\u0438\u043d\u0438\u043a\u0443 \u0441\u0430\u043c\u0438.\n\n## 6. \u0412\u044b\u043f\u043b\u0430\u0442\u044b\n\u0421\u0435\u0440\u0442\u0438\u0444\u0438\u043a\u0430\u0442 \u043d\u0430 \u043c\u0430\u0442\u0435\u0440\u0438\u043d\u0441\u043a\u0438\u0439 \u043a\u0430\u043f\u0438\u0442\u0430\u043b \u043e\u0431\u044b\u0447\u043d\u043e \u043e\u0444\u043e\u0440\u043c\u043b\u044f\u0435\u0442\u0441\u044f \u0430\u0432\u0442\u043e\u043c\u0430\u0442\u0438\u0447\u0435\u0441\u043a\u0438 \u043f\u043e\u0441\u043b\u0435\n\u0440\u0435\u0433\u0438\u0441\u0442\u0440\u0430\u0446\u0438\u0438 \u0440\u043e\u0436\u0434\u0435\u043d\u0438\u044f. \u041f\u043e\u0441\u043e\u0431\u0438\u044f \u043f\u0440\u0438 \u0440\u043e\u0436\u0434\u0435\u043d\u0438\u0438 \u0438 \u0435\u0436\u0435\u043c\u0435\u0441\u044f\u0447\u043d\u044b\u0435 \u0432\u044b\u043f\u043b\u0430\u0442\u044b \u043e\u0444\u043e\u0440\u043c\u043b\u044f\u044e\u0442\u0441\u044f\n\u043f\u043e \u0437\u0430\u044f\u0432\u043b\u0435\u043d\u0438\u044e \u043d\u0430 \u0413\u043e\u0441\u0443\u0441\u043b\u0443\u0433\u0430\u0445 \u0438\u043b\u0438 \u0432 \u0421\u043e\u0446\u0438\u0430\u043b\u044c\u043d\u043e\u043c \u0444\u043e\u043d\u0434\u0435. \u0421\u0443\u043c\u043c\u044b \u0438 \u0443\u0441\u043b\u043e\u0432\u0438\u044f \u043c\u0435\u043d\u044f\u044e\u0442\u0441\u044f \u2014\n\u0441\u043c\u043e\u0442\u0440\u0438\u0442\u0435 \u0430\u043a\u0442\u0443\u0430\u043b\u044c\u043d\u044b\u0435 \u043d\u0430 \u0413\u043e\u0441\u0443\u0441\u043b\u0443\u0433\u0430\u0445.\n\n\u041e\u0442\u043c\u0435\u0442\u044c\u0442\u0435 \u0441\u0440\u043e\u043a\u0438 \u0432 \u043a\u0430\u043b\u0435\u043d\u0434\u0430\u0440\u0435 \u043f\u0440\u0438\u043b\u043e\u0436\u0435\u043d\u0438\u044f, \u0447\u0442\u043e\u0431\u044b \u043d\u0438\u0447\u0435\u0433\u043e \u043d\u0435 \u043f\u0440\u043e\u043f\u0443\u0441\u0442\u0438\u0442\u044c.\n",B.jw,!1,0,90)
B.a8A=new A.hf("parents-rest",B.CB,"\u041a\u0430\u043a \u043e\u0442\u0434\u044b\u0445\u0430\u0442\u044c, \u043a\u043e\u0433\u0434\u0430 \u043c\u0430\u043b\u044b\u0448 \u043d\u0435 \u0441\u043f\u0438\u0442","\u0423\u0441\u0442\u0430\u043b\u043e\u0441\u0442\u044c \u0432 \u043f\u0435\u0440\u0432\u044b\u0435 \u043c\u0435\u0441\u044f\u0446\u044b \u2014 \u043d\u043e\u0440\u043c\u0430\u043b\u044c\u043d\u043e. \u041a\u0430\u043a \u0435\u0451 \u0434\u0435\u043b\u0438\u0442\u044c \u043d\u0430 \u0434\u0432\u043e\u0438\u0445 \u0438 \u043a\u043e\u0433\u0434\u0430 \u0441\u0442\u043e\u0438\u0442 \u043e\u0431\u0440\u0430\u0442\u0438\u0442\u044c\u0441\u044f \u0437\u0430 \u043f\u043e\u043c\u043e\u0449\u044c\u044e.","\u0425\u0440\u043e\u043d\u0438\u0447\u0435\u0441\u043a\u0438\u0439 \u043d\u0435\u0434\u043e\u0441\u044b\u043f \u2014 \u0433\u043b\u0430\u0432\u043d\u0430\u044f \u0442\u0440\u0443\u0434\u043d\u043e\u0441\u0442\u044c \u043f\u0435\u0440\u0432\u043e\u0433\u043e \u0433\u043e\u0434\u0430. \u0415\u0433\u043e \u043d\u0435 \u043f\u043e\u0431\u0435\u0434\u0438\u0442\u044c\n\u043f\u043e\u043b\u043d\u043e\u0441\u0442\u044c\u044e, \u043d\u043e \u043c\u043e\u0436\u043d\u043e \u0441\u0434\u0435\u043b\u0430\u0442\u044c \u0442\u0435\u0440\u043f\u0438\u043c\u0435\u0435.\n\n## \u0421\u043e\u043d \u0441\u043c\u0435\u043d\u0430\u043c\u0438\n\u0415\u0441\u043b\u0438 \u0432\u0430\u0441 \u0434\u0432\u043e\u0435, \u0434\u0435\u043b\u0438\u0442\u0435 \u043d\u043e\u0447\u044c: \u043e\u0434\u0438\u043d \u0441\u043f\u0438\u0442 \u0432 \u0442\u0438\u0448\u0438\u043d\u0435 \u0447\u0435\u0442\u044b\u0440\u0435-\u043f\u044f\u0442\u044c \u0447\u0430\u0441\u043e\u0432 \u043f\u043e\u0434\u0440\u044f\u0434,\n\u0434\u0440\u0443\u0433\u043e\u0439 \u0434\u0435\u0436\u0443\u0440\u0438\u0442, \u043f\u043e\u0442\u043e\u043c \u043c\u0435\u043d\u044f\u0435\u0442\u0435\u0441\u044c. \u041d\u0435\u043f\u0440\u0435\u0440\u044b\u0432\u043d\u044b\u0439 \u0441\u043e\u043d \u0432\u043e\u0441\u0441\u0442\u0430\u043d\u0430\u0432\u043b\u0438\u0432\u0430\u0435\u0442 \u043b\u0443\u0447\u0448\u0435,\n\u0447\u0435\u043c \u0441\u0442\u043e\u043b\u044c\u043a\u043e \u0436\u0435 \u0447\u0430\u0441\u043e\u0432 \u0443\u0440\u044b\u0432\u043a\u0430\u043c\u0438.\n\n## \u0421\u0430\u043c\u044b\u0439 \u043a\u043e\u0440\u043e\u0442\u043a\u0438\u0439 \u0441\u043f\u0438\u0441\u043e\u043a \u0434\u0435\u043b\n\u041a\u0430\u0436\u0434\u044b\u0439 \u0434\u0435\u043d\u044c \u0432\u044b\u0431\u0438\u0440\u0430\u0439\u0442\u0435 \u043e\u0434\u043d\u043e-\u0434\u0432\u0430 \u0434\u0435\u043b\u0430, \u043a\u043e\u0442\u043e\u0440\u044b\u0435 \u043f\u0440\u0430\u0432\u0434\u0430 \u043d\u0443\u0436\u043d\u044b. \u041e\u0441\u0442\u0430\u043b\u044c\u043d\u043e\u0435\n\u043f\u043e\u0434\u043e\u0436\u0434\u0451\u0442. \u0413\u043e\u0442\u043e\u0432\u0430\u044f \u0435\u0434\u0430, \u0434\u043e\u0441\u0442\u0430\u0432\u043a\u0430 \u0438 \u0431\u0443\u043c\u0430\u0436\u043d\u044b\u0435 \u0442\u0430\u0440\u0435\u043b\u043a\u0438 \u2014 \u043d\u043e\u0440\u043c\u0430\u043b\u044c\u043d\u044b\u0439 \u0432\u044b\u0431\u043e\u0440\n\u043d\u0430 \u043d\u0435\u0441\u043a\u043e\u043b\u044c\u043a\u043e \u043c\u0435\u0441\u044f\u0446\u0435\u0432.\n\n## \u0412\u0440\u0435\u043c\u044f \u0434\u043b\u044f \u0441\u0435\u0431\u044f\n\u041f\u044f\u0442\u043d\u0430\u0434\u0446\u0430\u0442\u044c \u043c\u0438\u043d\u0443\u0442 \u0432 \u0434\u0435\u043d\u044c \u0442\u043e\u043b\u044c\u043a\u043e \u0434\u043b\u044f \u0441\u0435\u0431\u044f \u2014 \u043f\u0440\u043e\u0433\u0443\u043b\u043a\u0430, \u0434\u0443\u0448 \u0431\u0435\u0437 \u0441\u043f\u0435\u0448\u043a\u0438, \u0437\u0432\u043e\u043d\u043e\u043a\n\u043f\u043e\u0434\u0440\u0443\u0433\u0435 \u0438\u043b\u0438 \u0434\u0440\u0443\u0433\u0443. \u0414\u043e\u0433\u043e\u0432\u043e\u0440\u0438\u0442\u0435\u0441\u044c \u043e \u043d\u0438\u0445 \u0441 \u043f\u0430\u0440\u0442\u043d\u0451\u0440\u043e\u043c \u0438\u043b\u0438 \u0431\u043b\u0438\u0437\u043a\u0438\u043c\u0438 \u0442\u0430\u043a \u0436\u0435\n\u0441\u0435\u0440\u044c\u0451\u0437\u043d\u043e, \u043a\u0430\u043a \u043e \u0432\u0438\u0437\u0438\u0442\u0435 \u043a \u0432\u0440\u0430\u0447\u0443.\n\n## \u041a\u043e\u0433\u0434\u0430 \u043d\u0443\u0436\u043d\u0430 \u043f\u043e\u043c\u043e\u0449\u044c \u0441\u043f\u0435\u0446\u0438\u0430\u043b\u0438\u0441\u0442\u0430\n\u0415\u0441\u043b\u0438 \u0434\u0432\u0435 \u043d\u0435\u0434\u0435\u043b\u0438 \u0438 \u0434\u043e\u043b\u044c\u0448\u0435 \u043f\u043e\u0447\u0442\u0438 \u0432\u0441\u0451 \u0432\u0440\u0435\u043c\u044f \u0442\u043e\u0441\u043a\u043b\u0438\u0432\u043e \u0438\u043b\u0438 \u0442\u0440\u0435\u0432\u043e\u0436\u043d\u043e, \u043d\u0438\u0447\u0435\u0433\u043e\n\u043d\u0435 \u0440\u0430\u0434\u0443\u0435\u0442, \u0442\u0440\u0443\u0434\u043d\u043e \u0437\u0430\u0431\u043e\u0442\u0438\u0442\u044c\u0441\u044f \u043e \u0441\u0435\u0431\u0435 \u0438 \u043c\u0430\u043b\u044b\u0448\u0435 \u0438\u043b\u0438 \u043f\u043e\u044f\u0432\u043b\u044f\u044e\u0442\u0441\u044f \u043f\u0443\u0433\u0430\u044e\u0449\u0438\u0435\n\u043c\u044b\u0441\u043b\u0438 \u2014 \u043e\u0431\u0440\u0430\u0442\u0438\u0442\u0435\u0441\u044c \u043a \u0432\u0440\u0430\u0447\u0443: \u0430\u043a\u0443\u0448\u0435\u0440\u0443-\u0433\u0438\u043d\u0435\u043a\u043e\u043b\u043e\u0433\u0443, \u0442\u0435\u0440\u0430\u043f\u0435\u0432\u0442\u0443 \u0438\u043b\u0438 \u043f\u0441\u0438\u0445\u043e\u0442\u0435\u0440\u0430\u043f\u0435\u0432\u0442\u0443.\n\u042d\u0442\u043e \u0431\u044b\u0432\u0430\u0435\u0442 \u0447\u0430\u0441\u0442\u043e, \u043d\u0435 \u0437\u0430\u0432\u0438\u0441\u0438\u0442 \u043e\u0442 \u0442\u043e\u0433\u043e, \u0445\u043e\u0440\u043e\u0448\u0430\u044f \u043b\u0438 \u0432\u044b \u043c\u0430\u043c\u0430 \u0438\u043b\u0438 \u043f\u0430\u043f\u0430,\n\u0438 \u0445\u043e\u0440\u043e\u0448\u043e \u043b\u0435\u0447\u0438\u0442\u0441\u044f.\n\n> \u0415\u0441\u043b\u0438 \u043f\u043e\u044f\u0432\u0438\u043b\u0438\u0441\u044c \u043c\u044b\u0441\u043b\u0438 \u043f\u0440\u0438\u0447\u0438\u043d\u0438\u0442\u044c \u0432\u0440\u0435\u0434 \u0441\u0435\u0431\u0435 \u0438\u043b\u0438 \u0440\u0435\u0431\u0451\u043d\u043a\u0443, \u0437\u0432\u043e\u043d\u0438\u0442\u0435 112 \u043f\u0440\u044f\u043c\u043e\n> \u0441\u0435\u0439\u0447\u0430\u0441 \u0438\u043b\u0438 \u043f\u043e\u043f\u0440\u043e\u0441\u0438\u0442\u0435 \u0431\u043b\u0438\u0437\u043a\u0438\u0445 \u043f\u043e\u0431\u044b\u0442\u044c \u0440\u044f\u0434\u043e\u043c.\n",B.eQ,!0,0,365)
B.a8K=new A.hf("app-records",B.xg,"\u041a\u0430\u043a \u0432\u0435\u0441\u0442\u0438 \u0437\u0430\u043f\u0438\u0441\u0438, \u0447\u0442\u043e\u0431\u044b \u043e\u043d\u0438 \u043f\u043e\u043c\u043e\u0433\u0430\u043b\u0438 \u0432\u0440\u0430\u0447\u0443","\u0427\u0442\u043e \u043e\u0442\u043c\u0435\u0447\u0430\u0442\u044c \u0432 \u0442\u0440\u0435\u043a\u0435\u0440\u0430\u0445 \u0438 \u043f\u0440\u0438\u043a\u043e\u0440\u043c\u0435, \u0447\u0442\u043e\u0431\u044b \u0441\u0432\u043e\u0434\u043a\u0430 \u0434\u043b\u044f \u0432\u0440\u0430\u0447\u0430 \u0431\u044b\u043b\u0430 \u043f\u043e\u043b\u043d\u043e\u0439, \u0438 \u0447\u0442\u043e \u0432 \u043d\u0435\u0451 \u043d\u0438\u043a\u043e\u0433\u0434\u0430 \u043d\u0435 \u043f\u043e\u043f\u0430\u0434\u0430\u0435\u0442.","\u0412\u0440\u0430\u0447\u0443 \u0432\u0430\u0436\u043d\u044b \u043d\u0435 \u0432\u0441\u0435 \u0437\u0430\u043f\u0438\u0441\u0438 \u043f\u043e\u0434\u0440\u044f\u0434, \u0430 \u043d\u0435\u0441\u043a\u043e\u043b\u044c\u043a\u043e \u0442\u043e\u0447\u043d\u044b\u0445 \u0444\u0430\u043a\u0442\u043e\u0432. \u0412\u043e\u0442 \u0447\u0442\u043e\n\u0441\u0442\u043e\u0438\u0442 \u043e\u0442\u043c\u0435\u0447\u0430\u0442\u044c.\n\n## \u0421\u043e\u043d \u0438 \u043f\u043e\u0434\u0433\u0443\u0437\u043d\u0438\u043a\u0438\n\u041d\u0435 \u043e\u0431\u044f\u0437\u0430\u0442\u0435\u043b\u044c\u043d\u043e \u0432\u0435\u0441\u0442\u0438 \u0438\u0445 \u043f\u043e\u0441\u0442\u043e\u044f\u043d\u043d\u043e. \u0414\u043e\u0441\u0442\u0430\u0442\u043e\u0447\u043d\u043e \u043d\u0435\u0441\u043a\u043e\u043b\u044c\u043a\u0438\u0445 \u0434\u043d\u0435\u0439 \u043f\u043e\u0434\u0440\u044f\u0434 \u043f\u0435\u0440\u0435\u0434\n\u043f\u0440\u0438\u0451\u043c\u043e\u043c \u0438\u043b\u0438 \u043a\u043e\u0433\u0434\u0430 \u0447\u0442\u043e-\u0442\u043e \u0432\u0430\u0441 \u0431\u0435\u0441\u043f\u043e\u043a\u043e\u0438\u0442 \u2014 \u0442\u043e\u0433\u0434\u0430 \u0432 \u0441\u0432\u043e\u0434\u043a\u0435 \u0431\u0443\u0434\u0443\u0442 \u0441\u0440\u0435\u0434\u043d\u0438\u0435\n\u0437\u043d\u0430\u0447\u0435\u043d\u0438\u044f \u0438 \u0441\u0430\u043c\u044b\u0435 \u043a\u043e\u0440\u043e\u0442\u043a\u0438\u0435 \u0438 \u0434\u043b\u0438\u043d\u043d\u044b\u0435 \u0434\u043d\u0438.\n\n## \u041f\u0440\u0438\u043a\u043e\u0440\u043c \u0438 \u0440\u0435\u0430\u043a\u0446\u0438\u0438\n\u041e\u0442\u043c\u0435\u0447\u0430\u0439\u0442\u0435 \u043d\u043e\u0432\u044b\u0439 \u043f\u0440\u043e\u0434\u0443\u043a\u0442 \u0432 \u0434\u0435\u043d\u044c, \u043a\u043e\u0433\u0434\u0430 \u0435\u0433\u043e \u0434\u0430\u043b\u0438, \u0438 \u0441\u0440\u0430\u0437\u0443 \u043f\u0438\u0448\u0438\u0442\u0435 \u0440\u0435\u0430\u043a\u0446\u0438\u044e,\n\u0435\u0441\u043b\u0438 \u043e\u043d\u0430 \u0431\u044b\u043b\u0430: \u0447\u0442\u043e \u0438\u043c\u0435\u043d\u043d\u043e \u0438 \u0447\u0435\u0440\u0435\u0437 \u0441\u043a\u043e\u043b\u044c\u043a\u043e \u0432\u0440\u0435\u043c\u0435\u043d\u0438. \u0420\u0435\u0430\u043a\u0446\u0438\u0438 \u0437\u0430 \u0432\u0441\u0451 \u0432\u0440\u0435\u043c\u044f\n\u043f\u043e\u043f\u0430\u0434\u0430\u044e\u0442 \u0432 \u0441\u0432\u043e\u0434\u043a\u0443 \u043e\u0442\u0434\u0435\u043b\u044c\u043d\u044b\u043c \u0440\u0430\u0437\u0434\u0435\u043b\u043e\u043c.\n\n## \u0420\u043e\u0441\u0442 \u0438 \u0432\u0435\u0441\n\u0417\u0430\u043f\u0438\u0441\u044b\u0432\u0430\u0439\u0442\u0435 \u0437\u0430\u043c\u0435\u0440\u044b \u0441 \u043f\u043b\u0430\u043d\u043e\u0432\u044b\u0445 \u043e\u0441\u043c\u043e\u0442\u0440\u043e\u0432. \u0412 \u0441\u0432\u043e\u0434\u043a\u0435 \u0432\u0438\u0434\u043d\u043e \u043f\u043e\u0441\u043b\u0435\u0434\u043d\u0438\u0435 \u0437\u043d\u0430\u0447\u0435\u043d\u0438\u044f\n\u0438 \u0438\u0437\u043c\u0435\u043d\u0435\u043d\u0438\u0435 \u0437\u0430 \u043f\u0435\u0440\u0438\u043e\u0434.\n\n## \u041f\u0440\u0438\u0432\u0438\u0432\u043a\u0438 \u0438 \u0430\u043b\u043b\u0435\u0440\u0433\u0438\u0438\n\u0417\u0430\u043f\u0438\u0441\u044b\u0432\u0430\u0439\u0442\u0435 \u043f\u0440\u0438\u0432\u0438\u0432\u043a\u0443 \u0432 \u0442\u043e\u0442 \u0436\u0435 \u0434\u0435\u043d\u044c \u0432\u043c\u0435\u0441\u0442\u0435 \u0441 \u0441\u0435\u0440\u0438\u0435\u0439 \u043f\u0440\u0435\u043f\u0430\u0440\u0430\u0442\u0430 \u2014 \u043e\u043d\u0430 \u0435\u0441\u0442\u044c\n\u0432 \u0441\u043f\u0440\u0430\u0432\u043a\u0435 \u0438\u043b\u0438 \u043d\u0430 \u043d\u0430\u043a\u043b\u0435\u0439\u043a\u0435 \u0432 \u043a\u0430\u0440\u0442\u0435. \u0415\u0441\u043b\u0438 \u0432\u044b \u043e\u043a\u0430\u0436\u0435\u0442\u0435\u0441\u044c \u0432 \u0434\u0440\u0443\u0433\u043e\u043c \u0433\u043e\u0440\u043e\u0434\u0435,\n\u0443 \u0432\u0440\u0430\u0447\u0430 \u0431\u0443\u0434\u0435\u0442 \u043f\u043e\u043b\u043d\u044b\u0439 \u0441\u043f\u0438\u0441\u043e\u043a.\n\n> \u0417\u0430\u043f\u0438\u0441\u0438 \u0434\u043d\u0435\u0432\u043d\u0438\u043a\u0430 \u2014 \u043b\u0438\u0447\u043d\u044b\u0435. \u0412 \u0441\u0432\u043e\u0434\u043a\u0443 \u0434\u043b\u044f \u0432\u0440\u0430\u0447\u0430 \u043e\u043d\u0438 \u043d\u0435 \u043f\u043e\u043f\u0430\u0434\u0430\u044e\u0442 \u043d\u0438\u043a\u043e\u0433\u0434\u0430.\n",B.jw,!1,null,null)
B.a8D=new A.hf("app-feeding-steps",B.xg,"\u041f\u0440\u0438\u043a\u043e\u0440\u043c \u043f\u043e \u0448\u0430\u0433\u0430\u043c: \u043a\u0430\u043a \u043e\u0442\u043c\u0435\u0447\u0430\u0442\u044c \u043f\u0440\u043e\u0431\u044b","\u041a\u0430\u043a \u0440\u0430\u0431\u043e\u0442\u0430\u0435\u0442 \u043f\u043b\u0430\u043d \u0438\u0437 \u043f\u044f\u0442\u0438 \u043f\u0440\u043e\u0431, \u0447\u0442\u043e \u0437\u043d\u0430\u0447\u0430\u0442 \u043a\u0440\u0443\u0436\u043a\u0438 \u0438 \u043f\u043e\u0447\u0435\u043c\u0443 \u043e\u0442\u043a\u0430\u0437 \u043d\u0435 \u043e\u0431\u043d\u0443\u043b\u044f\u0435\u0442 \u043f\u0440\u043e\u0433\u0440\u0435\u0441\u0441.","> \u041a\u043e\u0433\u0434\u0430 \u043d\u0430\u0447\u0438\u043d\u0430\u0442\u044c \u043f\u0440\u0438\u043a\u043e\u0440\u043c \u0438 \u0441 \u043a\u0430\u043a\u0438\u0445 \u043f\u0440\u043e\u0434\u0443\u043a\u0442\u043e\u0432 \u2014 \u0440\u0435\u0448\u0430\u0435\u0442 \u043f\u0435\u0434\u0438\u0430\u0442\u0440. \u041f\u0440\u0438\u043b\u043e\u0436\u0435\u043d\u0438\u0435\n> \u043f\u043e\u043c\u043e\u0433\u0430\u0435\u0442 \u0442\u043e\u043b\u044c\u043a\u043e \u0432\u0435\u0441\u0442\u0438 \u0437\u0430\u043f\u0438\u0441\u0438.\n\n## \u041f\u043b\u0430\u043d \u0438\u0437 \u043f\u044f\u0442\u0438 \u043f\u0440\u043e\u0431\n\u041a\u043e\u0433\u0434\u0430 \u0432\u044b \u0434\u043e\u0431\u0430\u0432\u043b\u044f\u0435\u0442\u0435 \u043f\u0440\u043e\u0434\u0443\u043a\u0442 \u0441 \u043e\u0442\u043c\u0435\u0442\u043a\u043e\u0439 \xab\u0412\u0432\u043e\u0434\u0438\u043c \u043f\u043e \u0448\u0430\u0433\u0430\u043c\xbb, \u0432 \u043a\u0430\u0440\u0442\u043e\u0447\u043a\u0435\n\u043f\u043e\u044f\u0432\u043b\u044f\u044e\u0442\u0441\u044f \u043f\u044f\u0442\u044c \u043a\u0440\u0443\u0436\u043a\u043e\u0432. \u041f\u043e\u0441\u043b\u0435 \u043a\u0430\u0436\u0434\u043e\u0439 \u043f\u0440\u043e\u0431\u044b \u043d\u0430\u0436\u043c\u0438\u0442\u0435 \u043d\u0430 \u0441\u043b\u0435\u0434\u0443\u044e\u0449\u0438\u0439 \u043a\u0440\u0443\u0436\u043e\u043a\n\u0438 \u0432\u044b\u0431\u0435\u0440\u0438\u0442\u0435, \u043a\u0430\u043a \u0432\u0441\u0451 \u043f\u0440\u043e\u0448\u043b\u043e:\n- \xab\u0421\u044a\u0435\u043b \u0445\u043e\u0442\u044c \u043d\u0435\u043c\u043d\u043e\u0433\u043e\xbb \u2014 \u0448\u0430\u0433 \u0437\u0430\u0441\u0447\u0438\u0442\u0430\u043d;\n- \xab\u041e\u0442\u043a\u0430\u0437\u0430\u043b\u0441\u044f\xbb \u2014 \u043f\u0440\u043e\u0431\u0430 \u0441\u043e\u0445\u0440\u0430\u043d\u0438\u0442\u0441\u044f \u0432 \u0438\u0441\u0442\u043e\u0440\u0438\u0438, \u043f\u0440\u043e\u0433\u0440\u0435\u0441\u0441 \u043d\u0435 \u0438\u0437\u043c\u0435\u043d\u0438\u0442\u0441\u044f;\n- \xab\u041f\u0440\u043e\u043f\u0443\u0441\u0442\u0438\u043b\u0438\xbb \u2014 \u043d\u0430\u043f\u0440\u0438\u043c\u0435\u0440, \u043c\u0430\u043b\u044b\u0448 \u043f\u0440\u0438\u0431\u043e\u043b\u0435\u043b.\n\n\u041e\u0434\u043d\u0430 \u043f\u0440\u043e\u0431\u0430 \u0432 \u0434\u0435\u043d\u044c. \u041f\u043e\u0441\u043b\u0435 \u043f\u044f\u0442\u043e\u0433\u043e \u0437\u0430\u0441\u0447\u0438\u0442\u0430\u043d\u043d\u043e\u0433\u043e \u0448\u0430\u0433\u0430 \u043f\u0440\u043e\u0434\u0443\u043a\u0442 \u043f\u0435\u0440\u0435\u0445\u043e\u0434\u0438\u0442\n\u0432 \u043e\u0431\u0449\u0438\u0439 \u0441\u043f\u0438\u0441\u043e\u043a.\n\n## \u041e\u0442\u043a\u0430\u0437 \u2014 \u044d\u0442\u043e \u043d\u043e\u0440\u043c\u0430\u043b\u044c\u043d\u043e\n\u041c\u0430\u043b\u044b\u0448\u0438 \u0447\u0430\u0441\u0442\u043e \u043e\u0442\u043a\u0430\u0437\u044b\u0432\u0430\u044e\u0442\u0441\u044f \u043e\u0442 \u043d\u043e\u0432\u043e\u0433\u043e \u0441 \u043f\u0435\u0440\u0432\u043e\u0433\u043e \u0440\u0430\u0437\u0430. \u041f\u043e\u043f\u0440\u043e\u0431\u0443\u0439\u0442\u0435 \u0432 \u0434\u0440\u0443\u0433\u043e\u0439 \u0434\u0435\u043d\u044c:\n\u043f\u0440\u0438\u043b\u043e\u0436\u0435\u043d\u0438\u0435 \u043d\u0435 \u043e\u0431\u043d\u0443\u043b\u044f\u0435\u0442 \u043f\u0440\u043e\u0433\u0440\u0435\u0441\u0441 \u0438 \u043d\u0435 \u0441\u0447\u0438\u0442\u0430\u0435\u0442 \u043e\u0442\u043a\u0430\u0437 \u043e\u0448\u0438\u0431\u043a\u043e\u0439.\n\n## \u0413\u0440\u0443\u043f\u043f\u044b \u0438 \u0440\u0430\u0437\u043d\u043e\u043e\u0431\u0440\u0430\u0437\u0438\u0435\n\u0413\u0440\u0443\u043f\u043f\u0443 \u043f\u0440\u043e\u0434\u0443\u043a\u0442\u0430 \u043f\u0440\u0438\u043b\u043e\u0436\u0435\u043d\u0438\u0435 \u0443\u0433\u0430\u0434\u044b\u0432\u0430\u0435\u0442 \u043f\u043e \u043d\u0430\u0437\u0432\u0430\u043d\u0438\u044e, \u0435\u0451 \u043c\u043e\u0436\u043d\u043e \u043f\u043e\u043c\u0435\u043d\u044f\u0442\u044c.\n\u0412 \u043a\u0430\u0440\u0442\u043e\u0447\u043a\u0435 \xab\u0420\u0430\u0437\u043d\u043e\u043e\u0431\u0440\u0430\u0437\u0438\u0435\xbb \u0432\u0438\u0434\u043d\u043e, \u0438\u0437 \u043a\u0430\u043a\u0438\u0445 \u0433\u0440\u0443\u043f\u043f \u043c\u0430\u043b\u044b\u0448 \u0443\u0436\u0435 \u043f\u0440\u043e\u0431\u043e\u0432\u0430\u043b.\n\n## \u0410\u043b\u043b\u0435\u0440\u0433\u0438\u0438\n\u0415\u0441\u043b\u0438 \u0432 \u043f\u0440\u043e\u0444\u0438\u043b\u0435 \u043e\u0442\u043c\u0435\u0447\u0435\u043d\u0430 \u0430\u043b\u043b\u0435\u0440\u0433\u0438\u044f, \u043f\u0440\u0438\u043b\u043e\u0436\u0435\u043d\u0438\u0435 \u043f\u0440\u0435\u0434\u0443\u043f\u0440\u0435\u0434\u0438\u0442, \u043a\u043e\u0433\u0434\u0430 \u0432 \u043d\u0430\u0437\u0432\u0430\u043d\u0438\u0438\n\u043d\u043e\u0432\u043e\u0433\u043e \u043f\u0440\u043e\u0434\u0443\u043a\u0442\u0430 \u0432\u0441\u0442\u0440\u0435\u0442\u0438\u0442\u0441\u044f \u044d\u0442\u043e\u0442 \u0430\u043b\u043b\u0435\u0440\u0433\u0435\u043d. \u042d\u0442\u043e \u043f\u043e\u0434\u0441\u043a\u0430\u0437\u043a\u0430, \u0430 \u043d\u0435 \u043f\u0440\u043e\u0432\u0435\u0440\u043a\u0430\n\u0441\u043e\u0441\u0442\u0430\u0432\u0430 \u2014 \u043e\u0431\u0441\u0443\u0436\u0434\u0430\u0439\u0442\u0435 \u0442\u0430\u043a\u0438\u0435 \u043f\u0440\u043e\u0434\u0443\u043a\u0442\u044b \u0441 \u0432\u0440\u0430\u0447\u043e\u043c.\n",B.jw,!1,null,null)
B.a8C=new A.hf("first-bath",B.ja,"\u041f\u0435\u0440\u0432\u043e\u0435 \u043a\u0443\u043f\u0430\u043d\u0438\u0435: \u0441\u043f\u043e\u043a\u043e\u0439\u043d\u043e \u0438 \u043f\u043e \u0448\u0430\u0433\u0430\u043c","\u0427\u0442\u043e \u043f\u043e\u0434\u0433\u043e\u0442\u043e\u0432\u0438\u0442\u044c, \u043a\u0430\u043a \u0434\u0435\u0440\u0436\u0430\u0442\u044c \u043c\u0430\u043b\u044b\u0448\u0430 \u0438 \u043a\u0430\u043a \u0441\u0434\u0435\u043b\u0430\u0442\u044c \u043a\u0443\u043f\u0430\u043d\u0438\u0435 \u043f\u0440\u0438\u044f\u0442\u043d\u044b\u043c \u0434\u043b\u044f \u0432\u0430\u0441 \u043e\u0431\u043e\u0438\u0445.","\u041f\u0435\u0440\u0432\u043e\u0435 \u043a\u0443\u043f\u0430\u043d\u0438\u0435 \u0447\u0430\u0441\u0442\u043e \u0432\u043e\u043b\u043d\u0443\u0435\u0442 \u0440\u043e\u0434\u0438\u0442\u0435\u043b\u0435\u0439 \u0431\u043e\u043b\u044c\u0448\u0435, \u0447\u0435\u043c \u043c\u0430\u043b\u044b\u0448\u0430. \u041a\u043e\u0433\u0434\u0430 \u043c\u043e\u0436\u043d\u043e\n\u043a\u0443\u043f\u0430\u0442\u044c \u0432 \u043f\u0435\u0440\u0432\u044b\u0439 \u0440\u0430\u0437 \u0438 \u043d\u0443\u0436\u043d\u043e \u043b\u0438 \u0436\u0434\u0430\u0442\u044c, \u043f\u043e\u043a\u0430 \u0437\u0430\u0436\u0438\u0432\u0451\u0442 \u043f\u0443\u043f\u043e\u0447\u043d\u0430\u044f \u0440\u0430\u043d\u043a\u0430, \u0443\u0442\u043e\u0447\u043d\u0438\u0442\u0435\n\u0443 \u043f\u0435\u0434\u0438\u0430\u0442\u0440\u0430 \u0438\u043b\u0438 \u043f\u0430\u0442\u0440\u043e\u043d\u0430\u0436\u043d\u043e\u0439 \u0441\u0435\u0441\u0442\u0440\u044b.\n\n## \u041f\u043e\u0434\u0433\u043e\u0442\u043e\u0432\u044c\u0442\u0435 \u0432\u0441\u0451 \u0437\u0430\u0440\u0430\u043d\u0435\u0435\n- \u0412\u0430\u043d\u043d\u043e\u0447\u043a\u0430 \u0438 \u043a\u043e\u0432\u0448 \u0438\u043b\u0438 \u043a\u0443\u0432\u0448\u0438\u043d \u0434\u043b\u044f \u043e\u043f\u043e\u043b\u0430\u0441\u043a\u0438\u0432\u0430\u043d\u0438\u044f.\n- \u0422\u0435\u0440\u043c\u043e\u043c\u0435\u0442\u0440 \u0434\u043b\u044f \u0432\u043e\u0434\u044b.\n- \u041c\u044f\u0433\u043a\u043e\u0435 \u043f\u043e\u043b\u043e\u0442\u0435\u043d\u0446\u0435 \u0441 \u0443\u0433\u043e\u043b\u043a\u043e\u043c, \u0447\u0438\u0441\u0442\u044b\u0439 \u043f\u043e\u0434\u0433\u0443\u0437\u043d\u0438\u043a \u0438 \u043e\u0434\u0435\u0436\u0434\u0430.\n- \u0414\u0435\u0442\u0441\u043a\u043e\u0435 \u0441\u0440\u0435\u0434\u0441\u0442\u0432\u043e \u0434\u043b\u044f \u043a\u0443\u043f\u0430\u043d\u0438\u044f, \u0435\u0441\u043b\u0438 \u0432\u0440\u0430\u0447 \u043d\u0435 \u043f\u0440\u043e\u0442\u0438\u0432. \u0412 \u043f\u0435\u0440\u0432\u044b\u0435 \u043d\u0435\u0434\u0435\u043b\u0438 \u0447\u0430\u0441\u0442\u043e\n  \u0445\u0432\u0430\u0442\u0430\u0435\u0442 \u043f\u0440\u043e\u0441\u0442\u043e \u0432\u043e\u0434\u044b.\n\n\u0420\u0430\u0437\u043b\u043e\u0436\u0438\u0442\u0435 \u0432\u0441\u0451 \u043d\u0430 \u0440\u0430\u0441\u0441\u0442\u043e\u044f\u043d\u0438\u0438 \u0432\u044b\u0442\u044f\u043d\u0443\u0442\u043e\u0439 \u0440\u0443\u043a\u0438: \u0432\u043e \u0432\u0440\u0435\u043c\u044f \u043a\u0443\u043f\u0430\u043d\u0438\u044f \u043e\u0442\u0445\u043e\u0434\u0438\u0442\u044c\n\u043e\u0442 \u0432\u0430\u043d\u043d\u043e\u0447\u043a\u0438 \u043d\u0435\u043b\u044c\u0437\u044f.\n\n## \u0412\u043e\u0434\u0430 \u0438 \u043a\u043e\u043c\u043d\u0430\u0442\u0430\n\u041e\u0431\u044b\u0447\u043d\u043e \u0441\u043e\u0432\u0435\u0442\u0443\u044e\u0442 \u0432\u043e\u0434\u0443 \u043e\u043a\u043e\u043b\u043e 37 \xb0C. \u041f\u0440\u043e\u0432\u0435\u0440\u044c\u0442\u0435 \u0435\u0451 \u0442\u0435\u0440\u043c\u043e\u043c\u0435\u0442\u0440\u043e\u043c \u0438\u043b\u0438 \u043b\u043e\u043a\u0442\u0435\u043c:\n\u0432\u043e\u0434\u0430 \u0434\u043e\u043b\u0436\u043d\u0430 \u0431\u044b\u0442\u044c \u0442\u0451\u043f\u043b\u043e\u0439, \u043d\u043e \u043d\u0435 \u0433\u043e\u0440\u044f\u0447\u0435\u0439. \u0412 \u043a\u043e\u043c\u043d\u0430\u0442\u0435 \u0442\u0435\u043f\u043b\u043e \u0438 \u043d\u0435\u0442 \u0441\u043a\u0432\u043e\u0437\u043d\u044f\u043a\u043e\u0432.\n\u0412\u043e\u0434\u044b \u043d\u0435\u043c\u043d\u043e\u0433\u043e \u2014 \u0442\u0430\u043a, \u0447\u0442\u043e\u0431\u044b \u043f\u043b\u0435\u0447\u0438 \u043c\u0430\u043b\u044b\u0448\u0430 \u043e\u0441\u0442\u0430\u0432\u0430\u043b\u0438\u0441\u044c \u043d\u0430\u0434 \u0432\u043e\u0434\u043e\u0439.\n\n## \u041a\u0430\u043a \u0434\u0435\u0440\u0436\u0430\u0442\u044c\n\u041e\u0434\u043d\u043e\u0439 \u0440\u0443\u043a\u043e\u0439 \u043f\u043e\u0434\u0434\u0435\u0440\u0436\u0438\u0432\u0430\u0439\u0442\u0435 \u0433\u043e\u043b\u043e\u0432\u0443 \u0438 \u043f\u043b\u0435\u0447\u0438: \u0437\u0430\u0442\u044b\u043b\u043e\u043a \u043c\u0430\u043b\u044b\u0448\u0430 \u043b\u0435\u0436\u0438\u0442 \u043d\u0430 \u0432\u0430\u0448\u0435\u043c\n\u0437\u0430\u043f\u044f\u0441\u0442\u044c\u0435, \u043f\u0430\u043b\u044c\u0446\u044b \u043e\u0431\u0445\u0432\u0430\u0442\u044b\u0432\u0430\u044e\u0442 \u0435\u0433\u043e \u043f\u043b\u0435\u0447\u043e. \u0412\u0442\u043e\u0440\u043e\u0439 \u0440\u0443\u043a\u043e\u0439 \u043c\u043e\u0439\u0442\u0435. \u041e\u043f\u0443\u0441\u043a\u0430\u0439\u0442\u0435 \u043c\u0430\u043b\u044b\u0448\u0430\n\u0432 \u0432\u043e\u0434\u0443 \u043c\u0435\u0434\u043b\u0435\u043d\u043d\u043e, \u043d\u043e\u0436\u043a\u0430\u043c\u0438 \u0432\u043f\u0435\u0440\u0451\u0434.\n\n## \u0421\u0430\u043c\u043e \u043a\u0443\u043f\u0430\u043d\u0438\u0435\n- \u041d\u0430\u0447\u0438\u043d\u0430\u0439\u0442\u0435 \u0441 \u0442\u0435\u043b\u0430, \u043b\u0438\u0446\u043e \u0438 \u0433\u043e\u043b\u043e\u0432\u0443 \u043c\u043e\u0439\u0442\u0435 \u0432 \u043a\u043e\u043d\u0446\u0435.\n- \u0411\u0435\u0440\u0435\u0436\u043d\u043e \u043f\u0440\u043e\u043c\u044b\u0432\u0430\u0439\u0442\u0435 \u0441\u043a\u043b\u0430\u0434\u043e\u0447\u043a\u0438 \u043d\u0430 \u0448\u0435\u0435, \u043f\u043e\u0434 \u043c\u044b\u0448\u043a\u0430\u043c\u0438 \u0438 \u0432 \u043f\u0430\u0445\u0443.\n- \u041f\u0435\u0440\u0432\u044b\u0435 \u043a\u0443\u043f\u0430\u043d\u0438\u044f \u043a\u043e\u0440\u043e\u0442\u043a\u0438\u0435: \u043d\u0435\u0441\u043a\u043e\u043b\u044c\u043a\u0438\u0445 \u043c\u0438\u043d\u0443\u0442 \u0434\u043e\u0441\u0442\u0430\u0442\u043e\u0447\u043d\u043e.\n\n## \u041f\u043e\u0441\u043b\u0435\n\u0417\u0430\u0432\u0435\u0440\u043d\u0438\u0442\u0435 \u043c\u0430\u043b\u044b\u0448\u0430 \u0432 \u043f\u043e\u043b\u043e\u0442\u0435\u043d\u0446\u0435 \u0441 \u0443\u0433\u043e\u043b\u043a\u043e\u043c \u043d\u0430 \u0433\u043e\u043b\u043e\u0432\u0443 \u0438 \u043f\u0440\u043e\u043c\u043e\u043a\u043d\u0438\u0442\u0435 \u043a\u043e\u0436\u0443, \u043d\u0435 \u0442\u0440\u0438\u0442\u0435.\n\u041e\u0441\u043e\u0431\u0435\u043d\u043d\u043e \u0442\u0449\u0430\u0442\u0435\u043b\u044c\u043d\u043e \u043f\u0440\u043e\u0441\u0443\u0448\u0438\u0442\u0435 \u0441\u043a\u043b\u0430\u0434\u043e\u0447\u043a\u0438. \u0415\u0441\u043b\u0438 \u0432\u0440\u0430\u0447 \u0434\u0430\u043b \u0440\u0435\u043a\u043e\u043c\u0435\u043d\u0434\u0430\u0446\u0438\u0438 \u043f\u043e \u0443\u0445\u043e\u0434\u0443\n\u0437\u0430 \u043f\u0443\u043f\u043e\u0447\u043d\u043e\u0439 \u0440\u0430\u043d\u043a\u043e\u0439, \u0432\u044b\u043f\u043e\u043b\u043d\u0438\u0442\u0435 \u0438\u0445 \u043f\u043e\u0441\u043b\u0435 \u043a\u0443\u043f\u0430\u043d\u0438\u044f.\n\n> \u041d\u0438\u043a\u043e\u0433\u0434\u0430 \u043d\u0435 \u043e\u0441\u0442\u0430\u0432\u043b\u044f\u0439\u0442\u0435 \u043c\u0430\u043b\u044b\u0448\u0430 \u0432 \u0432\u043e\u0434\u0435 \u043e\u0434\u043d\u043e\u0433\u043e, \u0434\u0430\u0436\u0435 \u043d\u0430 \u0441\u0435\u043a\u0443\u043d\u0434\u0443. \u0415\u0441\u043b\u0438 \u043d\u0443\u0436\u043d\u043e\n> \u043e\u0442\u043e\u0439\u0442\u0438, \u0437\u0430\u0432\u0435\u0440\u043d\u0438\u0442\u0435 \u0435\u0433\u043e \u0432 \u043f\u043e\u043b\u043e\u0442\u0435\u043d\u0446\u0435 \u0438 \u0432\u043e\u0437\u044c\u043c\u0438\u0442\u0435 \u0441 \u0441\u043e\u0431\u043e\u0439.\n\n> \u0415\u0441\u043b\u0438 \u043c\u0430\u043b\u044b\u0448 \u043f\u043b\u0430\u0447\u0435\u0442, \u044d\u0442\u043e \u043d\u043e\u0440\u043c\u0430\u043b\u044c\u043d\u043e: \u043c\u043d\u043e\u0433\u0438\u043c \u043d\u0443\u0436\u043d\u043e \u0432\u0440\u0435\u043c\u044f, \u0447\u0442\u043e\u0431\u044b \u043f\u0440\u0438\u0432\u044b\u043a\u043d\u0443\u0442\u044c.\n> \u0413\u043e\u0432\u043e\u0440\u0438\u0442\u0435 \u0441 \u043d\u0438\u043c \u0441\u043f\u043e\u043a\u043e\u0439\u043d\u043e \u0438 \u0434\u0435\u0440\u0436\u0438\u0442\u0435 \u0443\u0432\u0435\u0440\u0435\u043d\u043d\u043e.\n",B.eQ,!0,0,60)
B.a8G=new A.hf("diaper-change",B.ja,"\u041a\u0430\u043a \u043c\u0435\u043d\u044f\u0442\u044c \u043f\u043e\u0434\u0433\u0443\u0437\u043d\u0438\u043a: \u0431\u044b\u0441\u0442\u0440\u043e \u0438 \u0431\u0435\u0437 \u0441\u043b\u0451\u0437","\u041f\u043e\u0448\u0430\u0433\u043e\u0432\u043e: \u0447\u0442\u043e \u0434\u0435\u0440\u0436\u0430\u0442\u044c \u043f\u043e\u0434 \u0440\u0443\u043a\u043e\u0439, \u043a\u0430\u043a \u043f\u043e\u0434\u043c\u044b\u0432\u0430\u0442\u044c \u0438 \u043a\u0430\u043a \u0437\u0430\u0441\u0442\u0435\u0433\u043d\u0443\u0442\u044c \u043f\u043e\u0434\u0433\u0443\u0437\u043d\u0438\u043a, \u0447\u0442\u043e\u0431\u044b \u043e\u043d \u043d\u0435 \u043f\u0440\u043e\u0442\u0435\u043a\u0430\u043b.","\u0412 \u043f\u0435\u0440\u0432\u044b\u0435 \u043c\u0435\u0441\u044f\u0446\u044b \u043f\u043e\u0434\u0433\u0443\u0437\u043d\u0438\u043a \u043c\u0435\u043d\u044f\u044e\u0442 \u043c\u043d\u043e\u0433\u043e \u0440\u0430\u0437 \u0432 \u0434\u0435\u043d\u044c, \u0438 \u0443\u0436\u0435 \u0447\u0435\u0440\u0435\u0437 \u043d\u0435\u0434\u0435\u043b\u044e \u044d\u0442\u043e\n\u043f\u043e\u043b\u0443\u0447\u0430\u0435\u0442\u0441\u044f \u043f\u043e\u0447\u0442\u0438 \u043d\u0430 \u0430\u0432\u0442\u043e\u043c\u0430\u0442\u0435. \u0412\u043e\u0442 \u0447\u0442\u043e \u043f\u043e\u043c\u043e\u0433\u0430\u0435\u0442.\n\n## \u0412\u0441\u0451 \u043f\u043e\u0434 \u0440\u0443\u043a\u043e\u0439\n- \u0427\u0438\u0441\u0442\u044b\u0439 \u043f\u043e\u0434\u0433\u0443\u0437\u043d\u0438\u043a \u2014 \u0440\u0430\u0441\u0441\u0442\u0435\u0433\u043d\u0438\u0442\u0435 \u0435\u0433\u043e \u0437\u0430\u0440\u0430\u043d\u0435\u0435.\n- \u0412\u043b\u0430\u0436\u043d\u044b\u0435 \u0441\u0430\u043b\u0444\u0435\u0442\u043a\u0438 \u0438\u043b\u0438 \u0442\u0451\u043f\u043b\u0430\u044f \u0432\u043e\u0434\u0430 \u0438 \u0432\u0430\u0442\u043d\u044b\u0435 \u0434\u0438\u0441\u043a\u0438.\n- \u041f\u0435\u043b\u0451\u043d\u043a\u0430 \u0438\u043b\u0438 \u043f\u043e\u0434\u0441\u0442\u0438\u043b\u043a\u0430.\n- \u041f\u0430\u043a\u0435\u0442 \u0434\u043b\u044f \u0438\u0441\u043f\u043e\u043b\u044c\u0437\u043e\u0432\u0430\u043d\u043d\u043e\u0433\u043e \u043f\u043e\u0434\u0433\u0443\u0437\u043d\u0438\u043a\u0430.\n- \u0418\u0433\u0440\u0443\u0448\u043a\u0430, \u0447\u0442\u043e\u0431\u044b \u0437\u0430\u043d\u044f\u0442\u044c \u0440\u0443\u043a\u0438 \u043c\u0430\u043b\u044b\u0448\u0430.\n\n## \u0428\u0430\u0433 \u0437\u0430 \u0448\u0430\u0433\u043e\u043c\n- \u0423\u043b\u043e\u0436\u0438\u0442\u0435 \u043c\u0430\u043b\u044b\u0448\u0430 \u043d\u0430 \u0441\u043f\u0438\u043d\u0443 \u0438 \u0440\u0430\u0441\u0441\u0442\u0435\u0433\u043d\u0438\u0442\u0435 \u043f\u043e\u0434\u0433\u0443\u0437\u043d\u0438\u043a.\n- \u041f\u0435\u0440\u0435\u0434\u043d\u0435\u0439 \u0447\u0430\u0441\u0442\u044c\u044e \u0433\u0440\u044f\u0437\u043d\u043e\u0433\u043e \u043f\u043e\u0434\u0433\u0443\u0437\u043d\u0438\u043a\u0430 \u0443\u0431\u0435\u0440\u0438\u0442\u0435 \u043e\u0441\u043d\u043e\u0432\u043d\u043e\u0435, \u0441\u0432\u0435\u0440\u043d\u0438\u0442\u0435 \u0435\u0433\u043e\n  \u0438 \u043e\u0442\u043b\u043e\u0436\u0438\u0442\u0435.\n- \u041e\u0447\u0438\u0441\u0442\u0438\u0442\u0435 \u043a\u043e\u0436\u0443. \u0414\u0435\u0432\u043e\u0447\u0435\u043a \u043f\u043e\u0434\u043c\u044b\u0432\u0430\u044e\u0442 \u0441\u043f\u0435\u0440\u0435\u0434\u0438 \u043d\u0430\u0437\u0430\u0434. \u0423 \u043c\u0430\u043b\u044c\u0447\u0438\u043a\u043e\u0432 \u0431\u0435\u0440\u0435\u0436\u043d\u043e\n  \u043f\u0440\u043e\u043c\u043e\u0439\u0442\u0435 \u0441\u043a\u043b\u0430\u0434\u043e\u0447\u043a\u0438, \u043d\u0438\u0447\u0435\u0433\u043e \u043d\u0435 \u043e\u0442\u0442\u044f\u0433\u0438\u0432\u0430\u044f.\n- \u0415\u0441\u043b\u0438 \u0432 \u043a\u043e\u043c\u043d\u0430\u0442\u0435 \u0442\u0435\u043f\u043b\u043e, \u0434\u0430\u0439\u0442\u0435 \u043a\u043e\u0436\u0435 \u043f\u0430\u0440\u0443 \u043c\u0438\u043d\u0443\u0442 \u043f\u043e\u0434\u044b\u0448\u0430\u0442\u044c.\n- \u041f\u043e\u0434\u043b\u043e\u0436\u0438\u0442\u0435 \u0447\u0438\u0441\u0442\u044b\u0439 \u043f\u043e\u0434\u0433\u0443\u0437\u043d\u0438\u043a: \u0437\u0430\u0434\u043d\u044f\u044f \u0447\u0430\u0441\u0442\u044c \u2014 \u043d\u0430 \u0443\u0440\u043e\u0432\u043d\u0435 \u043f\u043e\u044f\u0441\u043d\u0438\u0446\u044b.\n- \u0417\u0430\u0441\u0442\u0435\u0433\u043d\u0438\u0442\u0435 \u0442\u0430\u043a, \u0447\u0442\u043e\u0431\u044b \u043c\u0435\u0436\u0434\u0443 \u043f\u043e\u044f\u0441\u043e\u043c \u0438 \u0436\u0438\u0432\u043e\u0442\u0438\u043a\u043e\u043c \u043f\u0440\u043e\u0445\u043e\u0434\u0438\u043b\u0438 \u0434\u0432\u0430 \u043f\u0430\u043b\u044c\u0446\u0430.\n  \u0420\u0430\u0441\u043f\u0440\u0430\u0432\u044c\u0442\u0435 \u043c\u0430\u043d\u0436\u0435\u0442\u044b \u043d\u0430 \u043d\u043e\u0436\u043a\u0430\u0445 \u043d\u0430\u0440\u0443\u0436\u0443 \u2014 \u0442\u0430\u043a \u043c\u0435\u043d\u044c\u0448\u0435 \u043f\u0440\u043e\u0442\u0435\u043a\u0430\u0435\u0442.\n\n## \u041f\u043e\u043a\u0430 \u043d\u0435 \u0437\u0430\u0436\u0438\u043b\u0430 \u043f\u0443\u043f\u043e\u0447\u043d\u0430\u044f \u0440\u0430\u043d\u043a\u0430\n\u041f\u043e\u0434\u0432\u043e\u0440\u0430\u0447\u0438\u0432\u0430\u0439\u0442\u0435 \u0432\u0435\u0440\u0445\u043d\u0438\u0439 \u043a\u0440\u0430\u0439 \u043f\u043e\u0434\u0433\u0443\u0437\u043d\u0438\u043a\u0430, \u0447\u0442\u043e\u0431\u044b \u043e\u043d \u043d\u0435 \u0442\u0451\u0440 \u043f\u0443\u043f\u043e\u043a. \u0423 \u043d\u0435\u043a\u043e\u0442\u043e\u0440\u044b\u0445\n\u043f\u043e\u0434\u0433\u0443\u0437\u043d\u0438\u043a\u043e\u0432 \u0434\u043b\u044f \u043d\u043e\u0432\u043e\u0440\u043e\u0436\u0434\u0451\u043d\u043d\u044b\u0445 \u0434\u043b\u044f \u044d\u0442\u043e\u0433\u043e \u0435\u0441\u0442\u044c \u0432\u044b\u0440\u0435\u0437.\n\n## \u041d\u043e\u0447\u044c\u044e\n\u041c\u0435\u043d\u044f\u0439\u0442\u0435 \u043f\u0440\u0438 \u043f\u0440\u0438\u0433\u043b\u0443\u0448\u0451\u043d\u043d\u043e\u043c \u0441\u0432\u0435\u0442\u0435 \u0438 \u0433\u043e\u0432\u043e\u0440\u0438\u0442\u0435 \u0442\u0438\u0445\u043e: \u0442\u0430\u043a \u043c\u0430\u043b\u044b\u0448\u0443 \u043b\u0435\u0433\u0447\u0435 \u0441\u043d\u043e\u0432\u0430\n\u0443\u0441\u043d\u0443\u0442\u044c.\n\n## \u041e\u0442\u043c\u0435\u0442\u044c\u0442\u0435 \u0432 \u0442\u0440\u0435\u043a\u0435\u0440\u0435\n\u041e\u0434\u043d\u0430 \u043a\u043d\u043e\u043f\u043a\u0430 \u2014 \xab+ \u041c\u043e\u043a\u0440\u044b\u0439\xbb \u0438\u043b\u0438 \xab+ \u0413\u0440\u044f\u0437\u043d\u044b\u0439\xbb. \u0415\u0441\u043b\u0438 \u0432\u0440\u0430\u0447 \u0441\u043f\u0440\u043e\u0441\u0438\u0442, \u0441\u043a\u043e\u043b\u044c\u043a\u043e\n\u043f\u043e\u0434\u0433\u0443\u0437\u043d\u0438\u043a\u043e\u0432 \u0432 \u0434\u0435\u043d\u044c, \u043e\u0442\u0432\u0435\u0442 \u0431\u0443\u0434\u0435\u0442 \u0432 \u0441\u0432\u043e\u0434\u043a\u0435.\n\n> \u041d\u0435 \u043e\u0441\u0442\u0430\u0432\u043b\u044f\u0439\u0442\u0435 \u043c\u0430\u043b\u044b\u0448\u0430 \u043d\u0430 \u043f\u0435\u043b\u0435\u043d\u0430\u043b\u044c\u043d\u043e\u043c \u0441\u0442\u043e\u043b\u0438\u043a\u0435 \u043e\u0434\u043d\u043e\u0433\u043e: \u0434\u0430\u0436\u0435 \u0441\u043e\u0432\u0441\u0435\u043c \u043c\u0430\u043b\u0435\u043d\u044c\u043a\u0438\u0435\n> \u0434\u0435\u0442\u0438 \u043d\u0435\u043e\u0436\u0438\u0434\u0430\u043d\u043d\u043e \u043f\u0435\u0440\u0435\u0432\u043e\u0440\u0430\u0447\u0438\u0432\u0430\u044e\u0442\u0441\u044f.\n\n> \u0415\u0441\u043b\u0438 \u043f\u043e\u043a\u0440\u0430\u0441\u043d\u0435\u043d\u0438\u0435 \u043f\u043e\u0434 \u043f\u043e\u0434\u0433\u0443\u0437\u043d\u0438\u043a\u043e\u043c \u043d\u0435 \u043f\u0440\u043e\u0445\u043e\u0434\u0438\u0442 \u0437\u0430 \u043f\u0430\u0440\u0443 \u0434\u043d\u0435\u0439, \u043f\u043e\u044f\u0432\u0438\u043b\u0438\u0441\u044c\n> \u043f\u0443\u0437\u044b\u0440\u044c\u043a\u0438 \u0438\u043b\u0438 \u0442\u0440\u0435\u0449\u0438\u043d\u043a\u0438 \u0438\u043b\u0438 \u043c\u0430\u043b\u044b\u0448\u0443 \u044f\u0432\u043d\u043e \u0431\u043e\u043b\u044c\u043d\u043e, \u043f\u043e\u043a\u0430\u0436\u0438\u0442\u0435 \u043a\u043e\u0436\u0443 \u043f\u0435\u0434\u0438\u0430\u0442\u0440\u0443.\n",B.eQ,!0,0,365)
B.a8E=new A.hf("baby-proofing",B.ja,"\u0414\u043e\u043c \u0433\u043e\u0442\u043e\u0432 \u043a \u043f\u043e\u043b\u0437\u0443\u043d\u043a\u0443: \u0447\u0442\u043e \u043f\u0440\u043e\u0432\u0435\u0440\u0438\u0442\u044c","\u041c\u0430\u043b\u044b\u0448 \u0432\u043e\u0442-\u0432\u043e\u0442 \u043d\u0430\u0447\u043d\u0451\u0442 \u043f\u043e\u043b\u0437\u0430\u0442\u044c. \u041f\u043e\u0441\u043c\u043e\u0442\u0440\u0438\u0442\u0435 \u043d\u0430 \u043a\u0432\u0430\u0440\u0442\u0438\u0440\u0443 \u0435\u0433\u043e \u0433\u043b\u0430\u0437\u0430\u043c\u0438 \u2014 \u0441 \u0443\u0440\u043e\u0432\u043d\u044f \u043f\u043e\u043b\u0430.","\u041a\u043e\u0433\u0434\u0430 \u043c\u0430\u043b\u044b\u0448 \u043d\u0430\u0447\u0438\u043d\u0430\u0435\u0442 \u043f\u0435\u0440\u0435\u0432\u043e\u0440\u0430\u0447\u0438\u0432\u0430\u0442\u044c\u0441\u044f \u0438 \u043f\u043e\u043b\u0437\u0430\u0442\u044c, \u043a\u0432\u0430\u0440\u0442\u0438\u0440\u0443 \u0441\u0442\u043e\u0438\u0442 \u043e\u0441\u043c\u043e\u0442\u0440\u0435\u0442\u044c\n\u0437\u0430\u043d\u043e\u0432\u043e. \u041b\u0443\u0447\u0448\u0435 \u0441\u0434\u0435\u043b\u0430\u0442\u044c \u044d\u0442\u043e \u0437\u0430\u0440\u0430\u043d\u0435\u0435, \u0434\u043e \u043f\u0435\u0440\u0432\u044b\u0445 \u043f\u0443\u0442\u0435\u0448\u0435\u0441\u0442\u0432\u0438\u0439 \u043f\u043e \u043a\u043e\u043c\u043d\u0430\u0442\u0430\u043c.\n\n## \u041e\u043f\u0443\u0441\u0442\u0438\u0442\u0435\u0441\u044c \u043d\u0430 \u0447\u0435\u0442\u0432\u0435\u0440\u0435\u043d\u044c\u043a\u0438\n\u041f\u0440\u043e\u043f\u043e\u043b\u0437\u0438\u0442\u0435 \u043f\u043e \u043a\u043e\u043c\u043d\u0430\u0442\u0430\u043c \u0441\u0430\u043c\u0438: \u0442\u0430\u043a \u0432\u0438\u0434\u043d\u043e \u043f\u0440\u043e\u0432\u043e\u0434\u0430, \u043c\u0435\u043b\u043e\u0447\u0438 \u043f\u043e\u0434 \u0434\u0438\u0432\u0430\u043d\u043e\u043c \u0438 \u0443\u0433\u043b\u044b\n\u043d\u0430 \u0443\u0440\u043e\u0432\u043d\u0435 \u0433\u043e\u043b\u043e\u0432\u044b \u043c\u0430\u043b\u044b\u0448\u0430.\n\n## \u0427\u0442\u043e \u0443\u0431\u0440\u0430\u0442\u044c \u0438 \u0437\u0430\u043a\u0440\u044b\u0442\u044c\n- \u0420\u043e\u0437\u0435\u0442\u043a\u0438 \u2014 \u0437\u0430\u0433\u043b\u0443\u0448\u043a\u0430\u043c\u0438.\n- \u041f\u0440\u043e\u0432\u043e\u0434\u0430 \u2014 \u0432 \u043a\u043e\u0440\u043e\u0431 \u0438\u043b\u0438 \u0437\u0430 \u043c\u0435\u0431\u0435\u043b\u044c.\n- \u041e\u0441\u0442\u0440\u044b\u0435 \u0443\u0433\u043b\u044b \u2014 \u043c\u044f\u0433\u043a\u0438\u043c\u0438 \u043d\u0430\u043a\u043b\u0430\u0434\u043a\u0430\u043c\u0438.\n- \u0411\u044b\u0442\u043e\u0432\u0443\u044e \u0445\u0438\u043c\u0438\u044e \u0438 \u043b\u0435\u043a\u0430\u0440\u0441\u0442\u0432\u0430 \u2014 \u0432\u044b\u0441\u043e\u043a\u043e \u0438 \u043f\u043e\u0434 \u0437\u0430\u043c\u043e\u043a.\n- \u041c\u043e\u043d\u0435\u0442\u044b, \u0431\u0430\u0442\u0430\u0440\u0435\u0439\u043a\u0438, \u043c\u0430\u0433\u043d\u0438\u0442\u044b, \u043f\u0443\u0433\u043e\u0432\u0438\u0446\u044b \u2014 \u0442\u0443\u0434\u0430, \u0433\u0434\u0435 \u043c\u0430\u043b\u044b\u0448 \u043d\u0435 \u0434\u043e\u0441\u0442\u0430\u043d\u0435\u0442.\n- \u041a\u043e\u043c\u043e\u0434\u044b \u0438 \u0441\u0442\u0435\u043b\u043b\u0430\u0436\u0438 \u2014 \u043f\u0440\u0438\u043a\u0440\u0435\u043f\u0438\u0442\u0435 \u043a \u0441\u0442\u0435\u043d\u0435, \u0447\u0442\u043e\u0431\u044b \u043d\u0435 \u043e\u043f\u0440\u043e\u043a\u0438\u043d\u0443\u043b\u0438\u0441\u044c.\n- \u041e\u043a\u043d\u0430 \u2014 \u043f\u043e\u0441\u0442\u0430\u0432\u044c\u0442\u0435 \u0431\u043b\u043e\u043a\u0438\u0440\u0430\u0442\u043e\u0440\u044b. \u041c\u043e\u0441\u043a\u0438\u0442\u043d\u0430\u044f \u0441\u0435\u0442\u043a\u0430 \u043d\u0435 \u0443\u0434\u0435\u0440\u0436\u0438\u0442 \u0440\u0435\u0431\u0451\u043d\u043a\u0430.\n- \u0428\u043d\u0443\u0440\u044b \u043e\u0442 \u0448\u0442\u043e\u0440 \u0438 \u0436\u0430\u043b\u044e\u0437\u0438 \u2014 \u043f\u043e\u0434\u0432\u044f\u0436\u0438\u0442\u0435 \u043f\u043e\u0432\u044b\u0448\u0435.\n\n## \u041a\u0443\u0445\u043d\u044f \u0438 \u0432\u0430\u043d\u043d\u0430\u044f\n- \u041f\u043e\u0432\u043e\u0440\u0430\u0447\u0438\u0432\u0430\u0439\u0442\u0435 \u0440\u0443\u0447\u043a\u0438 \u043a\u0430\u0441\u0442\u0440\u044e\u043b\u044c \u043a \u0441\u0442\u0435\u043d\u0435.\n- \u041d\u0435 \u0441\u0442\u0430\u0432\u044c\u0442\u0435 \u0433\u043e\u0440\u044f\u0447\u0435\u0435 \u043d\u0430 \u043a\u0440\u0430\u0439 \u0441\u0442\u043e\u043b\u0430 \u0438 \u043d\u0435 \u043f\u0435\u0439\u0442\u0435 \u0433\u043e\u0440\u044f\u0447\u0438\u0439 \u0447\u0430\u0439 \u0441 \u043c\u0430\u043b\u044b\u0448\u043e\u043c \u043d\u0430 \u0440\u0443\u043a\u0430\u0445.\n- \u041d\u0435 \u043e\u0441\u0442\u0430\u0432\u043b\u044f\u0439\u0442\u0435 \u0432\u043e\u0434\u0443 \u0432 \u0432\u0430\u043d\u043d\u0435 \u0438 \u0432\u0451\u0434\u0440\u0430\u0445.\n\n> \u0415\u0441\u043b\u0438 \u043c\u0430\u043b\u044b\u0448 \u0447\u0442\u043e-\u0442\u043e \u043f\u0440\u043e\u0433\u043b\u043e\u0442\u0438\u043b, \u043e\u0431\u0436\u0451\u0433\u0441\u044f \u0438\u043b\u0438 \u0443\u043f\u0430\u043b \u0438 \u0432\u0430\u0441 \u0447\u0442\u043e-\u0442\u043e \u0442\u0440\u0435\u0432\u043e\u0436\u0438\u0442,\n> \u0437\u0432\u043e\u043d\u0438\u0442\u0435 103 \u0438\u043b\u0438 112.\n",B.eQ,!1,120,540)
B.a8I=new A.hf("first-trip",B.ja,"\u041f\u0435\u0440\u0432\u0430\u044f \u043f\u043e\u0435\u0437\u0434\u043a\u0430 \u0441 \u043c\u0430\u043b\u044b\u0448\u043e\u043c: \u0447\u0435\u043a-\u043b\u0438\u0441\u0442","\u0414\u043e\u043a\u0443\u043c\u0435\u043d\u0442\u044b, \u0432\u0435\u0449\u0438 \u0432 \u0434\u043e\u0440\u043e\u0433\u0443 \u0438 \u043d\u0435\u0441\u043a\u043e\u043b\u044c\u043a\u043e \u043f\u0440\u0438\u0451\u043c\u043e\u0432, \u043a\u043e\u0442\u043e\u0440\u044b\u0435 \u0434\u0435\u043b\u0430\u044e\u0442 \u043f\u043e\u0435\u0437\u0434\u043a\u0443 \u0441\u043f\u043e\u043a\u043e\u0439\u043d\u0435\u0435.","\u041f\u0435\u0440\u0432\u0430\u044f \u043f\u043e\u0435\u0437\u0434\u043a\u0430 \u043a \u0431\u0430\u0431\u0443\u0448\u043a\u0435 \u0438\u043b\u0438 \u0432 \u043e\u0442\u043f\u0443\u0441\u043a \u2014 \u0446\u0435\u043b\u043e\u0435 \u0441\u043e\u0431\u044b\u0442\u0438\u0435. \u0421\u043f\u0438\u0441\u043e\u043a \u043d\u0438\u0436\u0435 \u043f\u043e\u043c\u043e\u0436\u0435\u0442\n\u043d\u0438\u0447\u0435\u0433\u043e \u043d\u0435 \u0437\u0430\u0431\u044b\u0442\u044c.\n\n## \u0414\u043e\u043a\u0443\u043c\u0435\u043d\u0442\u044b\n- \u0421\u0432\u0438\u0434\u0435\u0442\u0435\u043b\u044c\u0441\u0442\u0432\u043e \u043e \u0440\u043e\u0436\u0434\u0435\u043d\u0438\u0438 \u043c\u0430\u043b\u044b\u0448\u0430 \u2014 \u043e\u0440\u0438\u0433\u0438\u043d\u0430\u043b.\n- \u041f\u043e\u043b\u0438\u0441 \u041e\u041c\u0421 \u043c\u0430\u043b\u044b\u0448\u0430.\n- \u0414\u043b\u044f \u043f\u043e\u0435\u0437\u0434\u043a\u0438 \u0437\u0430 \u0433\u0440\u0430\u043d\u0438\u0446\u0443 \u0443 \u0440\u0435\u0431\u0451\u043d\u043a\u0430 \u0434\u043e\u043b\u0436\u0435\u043d \u0431\u044b\u0442\u044c \u0441\u0432\u043e\u0439 \u0437\u0430\u0433\u0440\u0430\u043d\u043f\u0430\u0441\u043f\u043e\u0440\u0442. \u041f\u0440\u0430\u0432\u0438\u043b\u0430\n  \u0434\u043b\u044f \u043f\u043e\u0435\u0437\u0434\u043a\u0438 \u0441 \u043e\u0434\u043d\u0438\u043c \u0438\u0437 \u0440\u043e\u0434\u0438\u0442\u0435\u043b\u0435\u0439 \u0438 \u0442\u0440\u0435\u0431\u043e\u0432\u0430\u043d\u0438\u044f \u0441\u0442\u0440\u0430\u043d \u043c\u0435\u043d\u044f\u044e\u0442\u0441\u044f \u2014 \u043f\u0440\u043e\u0432\u0435\u0440\u044c\u0442\u0435\n  \u0438\u0445 \u0437\u0430\u0440\u0430\u043d\u0435\u0435 \u043d\u0430 \u0413\u043e\u0441\u0443\u0441\u043b\u0443\u0433\u0430\u0445 \u0438 \u043d\u0430 \u0441\u0430\u0439\u0442\u0435 \u043f\u043e\u0441\u043e\u043b\u044c\u0441\u0442\u0432\u0430.\n- \u0421\u0432\u043e\u0434\u043a\u0430 \u0434\u043b\u044f \u0432\u0440\u0430\u0447\u0430 \u0438\u0437 \u043f\u0440\u0438\u043b\u043e\u0436\u0435\u043d\u0438\u044f \u0432 PDF: \u043f\u0440\u0438\u0432\u0438\u0432\u043a\u0438, \u0430\u043b\u043b\u0435\u0440\u0433\u0438\u0438 \u0438 \u0440\u0435\u0430\u043a\u0446\u0438\u0438\n  \u043f\u0440\u0438\u0433\u043e\u0434\u044f\u0442\u0441\u044f, \u0435\u0441\u043b\u0438 \u043f\u0440\u0438\u0434\u0451\u0442\u0441\u044f \u043e\u0431\u0440\u0430\u0442\u0438\u0442\u044c\u0441\u044f \u043a \u043d\u0435\u0437\u043d\u0430\u043a\u043e\u043c\u043e\u043c\u0443 \u0432\u0440\u0430\u0447\u0443.\n\n## \u0412 \u0434\u043e\u0440\u043e\u0433\u0443\n- \u041f\u043e\u0434\u0433\u0443\u0437\u043d\u0438\u043a\u0438 \u043d\u0430 \u0432\u0441\u044e \u0434\u043e\u0440\u043e\u0433\u0443 \u0438 \u0437\u0430\u043f\u0430\u0441 \u043d\u0430 \u0437\u0430\u0434\u0435\u0440\u0436\u043a\u0438.\n- \u0414\u0432\u0430 \u043a\u043e\u043c\u043f\u043b\u0435\u043a\u0442\u0430 \u0441\u043c\u0435\u043d\u043d\u043e\u0439 \u043e\u0434\u0435\u0436\u0434\u044b \u0434\u043b\u044f \u043c\u0430\u043b\u044b\u0448\u0430 \u0438 \u043e\u0434\u0438\u043d \u0434\u043b\u044f \u0432\u0430\u0441.\n- \u0415\u0434\u0430 \u0438 \u0432\u043e\u0434\u0430, \u0431\u0443\u0442\u044b\u043b\u043e\u0447\u043a\u0430, \u043d\u0430\u0433\u0440\u0443\u0434\u043d\u0438\u043a\u0438.\n- \u041f\u0435\u043b\u0451\u043d\u043a\u0430, \u0441\u0430\u043b\u0444\u0435\u0442\u043a\u0438, \u043f\u0430\u043a\u0435\u0442\u044b.\n- \u041b\u044e\u0431\u0438\u043c\u0430\u044f \u0438\u0433\u0440\u0443\u0448\u043a\u0430 \u0438 \u0447\u0442\u043e-\u043d\u0438\u0431\u0443\u0434\u044c \u043d\u043e\u0432\u043e\u0435, \u0447\u0442\u043e\u0431\u044b \u043e\u0442\u0432\u043b\u0435\u0447\u044c.\n- \u041b\u0435\u043a\u0430\u0440\u0441\u0442\u0432\u0430, \u043a\u043e\u0442\u043e\u0440\u044b\u0435 \u043d\u0430\u0437\u043d\u0430\u0447\u0438\u043b \u0432\u0440\u0430\u0447. \u0427\u0442\u043e \u0435\u0449\u0451 \u043f\u043e\u043b\u043e\u0436\u0438\u0442\u044c \u0432 \u0430\u043f\u0442\u0435\u0447\u043a\u0443, \u043e\u0431\u0441\u0443\u0434\u0438\u0442\u0435\n  \u0441 \u043f\u0435\u0434\u0438\u0430\u0442\u0440\u043e\u043c \u0437\u0430\u0440\u0430\u043d\u0435\u0435.\n\n## \u041a\u0430\u043a \u0441\u0434\u0435\u043b\u0430\u0442\u044c \u0434\u043e\u0440\u043e\u0433\u0443 \u043b\u0435\u0433\u0447\u0435\n- \u041f\u043b\u0430\u043d\u0438\u0440\u0443\u0439\u0442\u0435 \u0432\u044b\u0435\u0437\u0434 \u043d\u0430 \u0432\u0440\u0435\u043c\u044f \u0434\u043d\u0435\u0432\u043d\u043e\u0433\u043e \u0441\u043d\u0430.\n- \u0412 \u043c\u0430\u0448\u0438\u043d\u0435 \u043c\u0430\u043b\u044b\u0448 \u0435\u0434\u0435\u0442 \u0442\u043e\u043b\u044c\u043a\u043e \u0432 \u0430\u0432\u0442\u043e\u043a\u0440\u0435\u0441\u043b\u0435 \u043f\u043e \u0435\u0433\u043e \u0432\u0435\u0441\u0443 \u0438 \u0432\u043e\u0437\u0440\u0430\u0441\u0442\u0443.\n- \u0414\u0435\u043b\u0430\u0439\u0442\u0435 \u043e\u0441\u0442\u0430\u043d\u043e\u0432\u043a\u0438: \u043c\u0430\u043b\u044b\u0448\u0443 \u043d\u0443\u0436\u043d\u043e \u0440\u0430\u0437\u043c\u044f\u0442\u044c\u0441\u044f, \u0430 \u0432\u0430\u043c \u2014 \u043e\u0442\u0434\u043e\u0445\u043d\u0443\u0442\u044c.\n\n> \u041e\u0442\u043c\u0435\u0442\u044c\u0442\u0435 \u043f\u043e\u0435\u0437\u0434\u043a\u0443 \u0432 \u043a\u0430\u043b\u0435\u043d\u0434\u0430\u0440\u0435 \u043f\u0440\u0438\u043b\u043e\u0436\u0435\u043d\u0438\u044f, \u0447\u0442\u043e\u0431\u044b \u043d\u0435 \u043f\u0440\u043e\u043f\u0443\u0441\u0442\u0438\u0442\u044c \u043f\u0440\u0438\u0432\u0438\u0432\u043a\u0443\n> \u0438\u043b\u0438 \u0432\u0438\u0437\u0438\u0442 \u043a \u0432\u0440\u0430\u0447\u0443, \u043a\u043e\u0442\u043e\u0440\u044b\u0435 \u0432\u044b\u043f\u0430\u0434\u0430\u044e\u0442 \u043d\u0430 \u044d\u0442\u0438 \u0434\u0430\u0442\u044b.\n",B.eQ,!1,30,365)
B.a8F=new A.hf("family-advice",B.CB,"\u0421\u043e\u0432\u0435\u0442\u044b \u0441\u043e \u0432\u0441\u0435\u0445 \u0441\u0442\u043e\u0440\u043e\u043d: \u043a\u0430\u043a \u043d\u0435 \u0443\u0442\u043e\u043d\u0443\u0442\u044c","\u0411\u0430\u0431\u0443\u0448\u043a\u0438, \u043f\u043e\u0434\u0440\u0443\u0433\u0438, \u0441\u043e\u0441\u0435\u0434\u0438 \u043f\u043e \u043f\u043b\u043e\u0449\u0430\u0434\u043a\u0435 \u2014 \u0441\u043e\u0432\u0435\u0442\u043e\u0432 \u043c\u043d\u043e\u0433\u043e, \u0438 \u043e\u043d\u0438 \u0441\u043f\u043e\u0440\u044f\u0442 \u0434\u0440\u0443\u0433 \u0441 \u0434\u0440\u0443\u0433\u043e\u043c. \u041a\u0430\u043a \u0441\u043e\u0445\u0440\u0430\u043d\u0438\u0442\u044c \u0441\u043f\u043e\u043a\u043e\u0439\u0441\u0442\u0432\u0438\u0435.","\u0421\u043e\u0432\u0435\u0442\u044b \u0441\u044b\u043f\u043b\u044e\u0442\u0441\u044f \u043e\u0442\u043e\u0432\u0441\u044e\u0434\u0443 \u0438 \u0447\u0430\u0441\u0442\u043e \u043f\u0440\u043e\u0442\u0438\u0432\u043e\u0440\u0435\u0447\u0430\u0442 \u0434\u0440\u0443\u0433 \u0434\u0440\u0443\u0433\u0443. \u041e\u0431\u044b\u0447\u043d\u043e \u0437\u0430 \u043d\u0438\u043c\u0438\n\u0441\u0442\u043e\u0438\u0442 \u0437\u0430\u0431\u043e\u0442\u0430, \u043d\u043e \u0432\u044b\u0441\u043b\u0443\u0448\u0438\u0432\u0430\u0442\u044c \u0438\u0445 \u0431\u044b\u0432\u0430\u0435\u0442 \u043d\u0435\u043f\u0440\u043e\u0441\u0442\u043e.\n\n## \u0420\u0435\u0448\u0430\u0435\u0442\u0435 \u0432\u044b\n\u0412\u044b \u2014 \u0440\u043e\u0434\u0438\u0442\u0435\u043b\u0438, \u0438 \u043f\u043e\u0441\u043b\u0435\u0434\u043d\u0435\u0435 \u0441\u043b\u043e\u0432\u043e \u0437\u0430 \u0432\u0430\u043c\u0438. \u0412 \u0432\u043e\u043f\u0440\u043e\u0441\u0430\u0445 \u0437\u0434\u043e\u0440\u043e\u0432\u044c\u044f \u043e\u0440\u0438\u0435\u043d\u0442\u0438\u0440\u0443\u0439\u0442\u0435\u0441\u044c\n\u043d\u0430 \u0441\u0432\u043e\u0435\u0433\u043e \u043f\u0435\u0434\u0438\u0430\u0442\u0440\u0430, \u0430 \u043d\u0435 \u043d\u0430 \u043e\u043f\u044b\u0442 \u0437\u043d\u0430\u043a\u043e\u043c\u044b\u0445: \u043c\u043d\u043e\u0433\u0438\u0435 \u0440\u0435\u043a\u043e\u043c\u0435\u043d\u0434\u0430\u0446\u0438\u0438 \u0437\u0430 \u043f\u043e\u0441\u043b\u0435\u0434\u043d\u0438\u0435\n\u0433\u043e\u0434\u044b \u0438\u0437\u043c\u0435\u043d\u0438\u043b\u0438\u0441\u044c.\n\n## \u0413\u043e\u0442\u043e\u0432\u044b\u0435 \u0444\u0440\u0430\u0437\u044b\n- \xab\u0421\u043f\u0430\u0441\u0438\u0431\u043e, \u043c\u044b \u043f\u043e\u0434\u0443\u043c\u0430\u0435\u043c\xbb.\n- \xab\u0422\u0430\u043a \u043f\u043e\u0441\u043e\u0432\u0435\u0442\u043e\u0432\u0430\u043b \u043d\u0430\u0448 \u0432\u0440\u0430\u0447. \u0414\u0430\u0432\u0430\u0439 \u0441\u043f\u0440\u043e\u0441\u0438\u043c \u0435\u0433\u043e \u0432\u043c\u0435\u0441\u0442\u0435 \u0432 \u0441\u043b\u0435\u0434\u0443\u044e\u0449\u0438\u0439 \u0440\u0430\u0437\xbb.\n- \xab\u041f\u043e\u043a\u0430 \u0443 \u043d\u0430\u0441 \u043f\u043e\u043b\u0443\u0447\u0430\u0435\u0442\u0441\u044f \u0442\u0430\u043a. \u0415\u0441\u043b\u0438 \u043d\u0435 \u0432\u044b\u0439\u0434\u0435\u0442 \u2014 \u043f\u043e\u043f\u0440\u043e\u0431\u0443\u0435\u043c \u043f\u043e-\u0434\u0440\u0443\u0433\u043e\u043c\u0443\xbb.\n\n## \u0414\u043e\u0433\u043e\u0432\u043e\u0440\u0438\u0442\u0435\u0441\u044c \u0434\u0440\u0443\u0433 \u0441 \u0434\u0440\u0443\u0433\u043e\u043c\n\u041e\u0431\u0441\u0443\u0434\u0438\u0442\u0435 \u0437\u0430\u0440\u0430\u043d\u0435\u0435, \u0447\u0442\u043e \u0434\u043b\u044f \u0432\u0430\u0441 \u0432\u0430\u0436\u043d\u043e, \u0438 \u043e\u0442\u0432\u0435\u0447\u0430\u0439\u0442\u0435 \u0440\u043e\u0434\u0441\u0442\u0432\u0435\u043d\u043d\u0438\u043a\u0430\u043c \u0432\u043c\u0435\u0441\u0442\u0435.\n\u0421\u043e \u0441\u0432\u043e\u0438\u043c\u0438 \u0440\u043e\u0434\u0438\u0442\u0435\u043b\u044f\u043c\u0438 \u043f\u0443\u0441\u0442\u044c \u0433\u043e\u0432\u043e\u0440\u0438\u0442 \u0442\u043e\u0442, \u0447\u044c\u0438 \u044d\u0442\u043e \u0440\u043e\u0434\u0438\u0442\u0435\u043b\u0438: \u0442\u0430\u043a \u043c\u0435\u043d\u044c\u0448\u0435 \u043e\u0431\u0438\u0434.\n\n## \u041f\u0440\u0435\u0432\u0440\u0430\u0442\u0438\u0442\u0435 \u0437\u0430\u0431\u043e\u0442\u0443 \u0432 \u043f\u043e\u043c\u043e\u0449\u044c\n\u041f\u0440\u0435\u0434\u043b\u043e\u0436\u0438\u0442\u0435 \u043a\u043e\u043d\u043a\u0440\u0435\u0442\u043d\u043e\u0435 \u0434\u0435\u043b\u043e: \u043f\u043e\u0433\u0443\u043b\u044f\u0442\u044c \u0441 \u043a\u043e\u043b\u044f\u0441\u043a\u043e\u0439, \u043f\u0440\u0438\u0433\u043e\u0442\u043e\u0432\u0438\u0442\u044c \u0443\u0436\u0438\u043d, \u043f\u043e\u0431\u044b\u0442\u044c\n\u0441 \u043c\u0430\u043b\u044b\u0448\u043e\u043c, \u043f\u043e\u043a\u0430 \u0432\u044b \u0441\u043f\u0438\u0442\u0435. \u0422\u0430\u043a \u0441\u043e\u0432\u0435\u0442\u044b \u043f\u0440\u0435\u0432\u0440\u0430\u0449\u0430\u044e\u0442\u0441\u044f \u0432 \u0440\u0435\u0430\u043b\u044c\u043d\u0443\u044e \u043f\u043e\u043c\u043e\u0449\u044c.\n",B.eQ,!1,null,null)
B.a8z=new A.hf("memory-diary",B.xg,"\u0414\u043d\u0435\u0432\u043d\u0438\u043a \u043d\u0430 \u043f\u0430\u043c\u044f\u0442\u044c: \u0447\u0442\u043e \u0437\u0430\u043f\u0438\u0441\u044b\u0432\u0430\u0442\u044c","\u0427\u0435\u0440\u0435\u0437 \u0433\u043e\u0434 \u043c\u043d\u043e\u0433\u043e\u0435 \u0437\u0430\u0431\u0443\u0434\u0435\u0442\u0441\u044f. \u041d\u0435\u0441\u043a\u043e\u043b\u044c\u043a\u043e \u0438\u0434\u0435\u0439, \u043a\u0430\u043a \u0441\u043e\u0445\u0440\u0430\u043d\u0438\u0442\u044c \u0433\u043b\u0430\u0432\u043d\u043e\u0435 \u0438 \u043d\u0435 \u0442\u0440\u0430\u0442\u0438\u0442\u044c \u043d\u0430 \u044d\u0442\u043e \u043c\u043d\u043e\u0433\u043e \u0432\u0440\u0435\u043c\u0435\u043d\u0438.","\u041f\u0435\u0440\u0432\u0430\u044f \u0443\u043b\u044b\u0431\u043a\u0430, \u0441\u043c\u0435\u0448\u043d\u044b\u0435 \u0437\u0432\u0443\u043a\u0438, \u043a\u0430\u043a \u043c\u0430\u043b\u044b\u0448 \u0437\u0430\u0441\u044b\u043f\u0430\u043b \u0443 \u043f\u0430\u043f\u044b \u043d\u0430 \u0433\u0440\u0443\u0434\u0438 \u2014 \u0447\u0435\u0440\u0435\u0437 \u0433\u043e\u0434\n\u044d\u0442\u043e \u0441\u043e\u0442\u0440\u0451\u0442\u0441\u044f \u0438\u0437 \u043f\u0430\u043c\u044f\u0442\u0438. \u0414\u043d\u0435\u0432\u043d\u0438\u043a \u043f\u043e\u043c\u043e\u0433\u0430\u0435\u0442 \u044d\u0442\u043e \u0441\u043e\u0445\u0440\u0430\u043d\u0438\u0442\u044c.\n\n## \u041a\u043e\u0440\u043e\u0442\u043a\u043e, \u043d\u043e \u0447\u0430\u0441\u0442\u043e\n\u041f\u0430\u0440\u0430 \u0441\u0442\u0440\u043e\u043a \u0432 \u0434\u0435\u043d\u044c \u0440\u0435\u0430\u043b\u044c\u043d\u0435\u0435, \u0447\u0435\u043c \u043f\u043e\u0434\u0440\u043e\u0431\u043d\u044b\u0439 \u0440\u0430\u0441\u0441\u043a\u0430\u0437 \u0440\u0430\u0437 \u0432 \u043c\u0435\u0441\u044f\u0446. \u041f\u0435\u0440\u0432\u0430\u044f\n\u0441\u0442\u0440\u043e\u043a\u0430 \u0437\u0430\u043f\u0438\u0441\u0438 \u043f\u043e\u043f\u0430\u0434\u0430\u0435\u0442 \u0432 \xab\u0418\u0442\u043e\u0433\u0438 \u043c\u0435\u0441\u044f\u0446\u0430\xbb, \u043f\u043e\u044d\u0442\u043e\u043c\u0443 \u043d\u0430\u0447\u0438\u043d\u0430\u0439\u0442\u0435 \u0441 \u0433\u043b\u0430\u0432\u043d\u043e\u0433\u043e.\n\n## \u0418\u0434\u0435\u0438 \u0434\u043b\u044f \u0437\u0430\u043f\u0438\u0441\u0435\u0439\n- \u041f\u0435\u0440\u0432\u044b\u0435 \u0440\u0430\u0437\u044b: \u0443\u043b\u044b\u0431\u043a\u0430, \u0441\u043c\u0435\u0445, \u043f\u0435\u0440\u0435\u0432\u043e\u0440\u043e\u0442, \u0437\u0443\u0431, \u0448\u0430\u0433.\n- \u0421\u043c\u0435\u0448\u043d\u044b\u0435 \u043c\u043e\u043c\u0435\u043d\u0442\u044b \u0438 \u043f\u0435\u0440\u0432\u044b\u0435 \xab\u0441\u043b\u043e\u0432\u0430\xbb.\n- \u041a\u0442\u043e \u043f\u0440\u0438\u0445\u043e\u0434\u0438\u043b \u0432 \u0433\u043e\u0441\u0442\u0438 \u0438 \u0447\u0442\u043e \u043f\u043e\u0434\u0430\u0440\u0438\u043b.\n- \u041a\u0430\u043a \u0432\u044b \u0441\u0435\u0431\u044f \u0447\u0443\u0432\u0441\u0442\u0432\u043e\u0432\u0430\u043b\u0438 \u2014 \u044d\u0442\u043e \u0442\u043e\u0436\u0435 \u0447\u0430\u0441\u0442\u044c \u0438\u0441\u0442\u043e\u0440\u0438\u0438.\n- \u041e\u0434\u043d\u043e \u0444\u043e\u0442\u043e \u0432 \u043d\u0435\u0434\u0435\u043b\u044e \u0432 \u043e\u0434\u043d\u043e\u043c \u0438 \u0442\u043e\u043c \u0436\u0435 \u043c\u0435\u0441\u0442\u0435: \u0447\u0435\u0440\u0435\u0437 \u0433\u043e\u0434 \u0431\u0443\u0434\u0435\u0442 \u0432\u0438\u0434\u043d\u043e,\n  \u043a\u0430\u043a \u043c\u0430\u043b\u044b\u0448 \u0432\u044b\u0440\u043e\u0441.\n\n## \u041d\u0430\u0432\u044b\u043a\u0438 \u0438 \u0438\u0442\u043e\u0433\u0438 \u043c\u0435\u0441\u044f\u0446\u0430\n\u041e\u0442\u043c\u0435\u0447\u0430\u0439\u0442\u0435 \u043d\u043e\u0432\u043e\u0435 \u0432 \u0440\u0430\u0437\u0434\u0435\u043b\u0435 \xab\u041d\u0430\u0432\u044b\u043a\u0438\xbb. \u0412 \u0434\u043d\u0435\u0432\u043d\u0438\u043a\u0435 \u0432\u044b\u0431\u0435\u0440\u0438\u0442\u0435 \u043c\u0435\u0441\u044f\u0446 \u2014 \u0442\u0430\u043c \u0438\u0442\u043e\u0433\u0438:\n\u0437\u0430\u043f\u0438\u0441\u0438 \u0438 \u0444\u043e\u0442\u043e, \u043d\u043e\u0432\u044b\u0435 \u043f\u0440\u043e\u0434\u0443\u043a\u0442\u044b \u0438 \u043d\u0430\u0432\u044b\u043a\u0438, \u0438\u0437\u043c\u0435\u043d\u0435\u043d\u0438\u0435 \u0432\u0435\u0441\u0430.\n\n> \u0417\u0430\u043f\u0438\u0441\u0438 \u0434\u043d\u0435\u0432\u043d\u0438\u043a\u0430 \u043b\u0438\u0447\u043d\u044b\u0435: \u043e\u043d\u0438 \u0445\u0440\u0430\u043d\u044f\u0442\u0441\u044f \u043d\u0430 \u0442\u0435\u043b\u0435\u0444\u043e\u043d\u0435 \u0438 \u043d\u0435 \u043f\u043e\u043f\u0430\u0434\u0430\u044e\u0442 \u0432 \u0441\u0432\u043e\u0434\u043a\u0443\n> \u0434\u043b\u044f \u0432\u0440\u0430\u0447\u0430.\n",B.eQ,!1,null,null)
